  ('aabb95db-03a6-5046-b03d-1ff5de6e3085', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дашо, оприлюднили рейтинговий список?", "Ти вивчила всі формули?", "Коли екскурсія?"]'::jsonb, 2, null, 'Kada je izlet?', null, null, 'Прозвучало: «Kada je izlet?» — «Коли екскурсія?».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('293bf60f-b023-5bc0-96e9-c6085b3e7d6b', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дар’є, що пише в листі?", "Скільки коштує навчання? Можна платити частинами?", "Вони там роблять домашнє завдання?"]'::jsonb, 0, null, 'Darja, što piše u pismu?', null, null, 'Прозвучало: «Darja, što piše u pismu?» — «Дар’є, що пише в листі?».', (select id from public.lessons where id = 'dd6c5f39-f66e-5acb-8255-932f822ddcc5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7f4943ef-fad3-58c7-8687-b3f190cfda97', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Хочу, дякую! Без нього я б не знала, як повторити матеріал.", "Він хотів би грати у водне поло, але внесок дорогий.", "П’ятсот євро, трьома частинами. Записуємо до п’ятнадцятого вересня."]'::jsonb, 2, null, 'Petsto eura, u tri rate. Upisujemo do petnaestog rujna.', null, null, 'Прозвучало: «Petsto eura, u tri rate. Upisujemo do petnaestog rujna.» — «П’ятсот євро, трьома частинами. Записуємо до п’ятнадцятого вересня.».', (select id from public.lessons where id = '8190831a-549a-544a-962b-4f716a895a32'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('4f84fe31-f653-57dc-a61e-7e69822550b1', v_aid, 4, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["На денній. Я подамся ще й на гуртожиток.", "Бухгалтери затребувані. Ви можете отримати ваучер на навчання.", "Може, у нас група продовженого дня до п’ятої."]'::jsonb, 1, null, 'Knjigovođe su traženi. Možete dobiti vaučer za obrazovanje.', null, null, 'Прозвучало: «Knjigovođe su traženi. Možete dobiti vaučer za obrazovanje.» — «Бухгалтери затребувані. Ви можете отримати ваучер на навчання.».', (select id from public.lessons where id = '24894494-1af7-5153-a7b0-7f0ef3c0bdce'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('09c61c9c-a7dc-5df3-a212-4c6fefef7b9e', v_aid, 5, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["П’ятнадцятого травня, їдемо в Крапину.", "Чотири місяці. Половина — практичне навчання в майстерні.", "Я маю доповнити заяву протягом восьми днів."]'::jsonb, 1, null, 'Četiri mjeseca. Pola je praktična nastava u radionici.', null, null, 'Прозвучало: «Četiri mjeseca. Pola je praktična nastava u radionici.» — «Чотири місяці. Половина — практичне навчання в майстерні.».', (select id from public.lessons where id = '24894494-1af7-5153-a7b0-7f0ef3c0bdce'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0c8c1675-9c41-5299-94dc-7bae9cdf8e20', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Čestitam! Hoćeš li biti redoviti ili izvanredni student?', '["Ulov dana je brancin. Može na žaru, s blitvom.", "Trideset posto. Boravišna pristojba se plaća na dolasku.", "Redoviti. Prijavit ću se i za studentski dom."]'::jsonb, 2, null, 'Čestitam! Hoćeš li biti redoviti ili izvanredni student?', null, null, 'Діалог «Результати»: «Čestitam! Hoćeš li biti redoviti ili izvanredni student?» (Вітаю! Ти будеш на денній чи на заочній?) — «Redoviti. Prijavit ću se i za studentski dom.» (На денній. Я подамся ще й на гуртожиток.).', (select id from public.lessons where id = 'aad2c656-7750-545f-88be-b36c1cdb3b79'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a81f9702-684e-5ff4-ae2e-df5565cd34d2', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li tečaj onda besplatan?', '["Jest. Na kraju polažete stručni ispit i dobivate uvjerenje.", "Oko četiri sata. Obvezno ponesi udobnu obuću.", "Mi bismo htjeli neko mirno mjesto, bez velike gužve."]'::jsonb, 0, null, 'Je li tečaj onda besplatan?', null, null, 'Діалог «У консультанта»: «Je li tečaj onda besplatan?» (Тоді курс безкоштовний?) — «Jest. Na kraju polažete stručni ispit i dobivate uvjerenje.» (Так. Наприкінці складаєте кваліфікаційний іспит і отримуєте свідоцтво.).', (select id from public.lessons where id = '24894494-1af7-5153-a7b0-7f0ef3c0bdce'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5cd88989-5f67-5c23-9383-ffd01afc91e6', v_aid, 8, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Gdje je raspored aktivnosti?', '["Htjela sam, ali termin u devet je rasprodan.", "Na vratima učionice. Samo ispuniš upisnicu.", "Do osamsto eura za četvero, ako je moguće."]'::jsonb, 1, null, 'Gdje je raspored aktivnosti?', null, null, 'Діалог «Який гурток?»: «Gdje je raspored aktivnosti?» (Де розклад гуртків?) — «Na vratima učionice. Samo ispuniš upisnicu.» (На дверях класу. Просто заповнюєш бланк запису.).', (select id from public.lessons where id = 'f0e24e2b-9e73-5a70-8f2f-ec825b0308e2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('78bf5e17-2675-5bbf-9eb3-6c207bda53e1', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Koliko traje postupak?', '["Засвідчена копія диплома з апостилем і виписка оцінок, з перекладом.", "До шістдесяти днів. Адміністративний збір сплачують перед поданням.", "Медсестра — регульована професія, тому потрібне професійне визнання."]'::jsonb, 1, null, null, 'Darja: Dobar dan, završila sam medicinsku školu u Ukrajini. Kako se priznaje diploma?
Službenica: Medicinska sestra je regulirana profesija, pa treba stručno priznavanje.
Darja: Što se prilaže uz zahtjev?
Službenica: Ovjerena preslika diplome s apostilleom i prijepis ocjena, s prijevodom.
Darja: Koliko traje postupak?
Službenica: Do šezdeset dana. Upravna pristojba se plaća prije predaje.', 'Darja: Добрий день, я закінчила медичне училище в Україні. Як визнається диплом?
Službenica: Медсестра — регульована професія, тому потрібне професійне визнання.
Darja: Що додається до заяви?
Službenica: Засвідчена копія диплома з апостилем і виписка оцінок, з перекладом.
Darja: Скільки триває процедура?
Službenica: До шістдесяти днів. Адміністративний збір сплачують перед поданням.', 'Діалог «Які документи?»: «Koliko traje postupak?» — «Do šezdeset dana. Upravna pristojba se plaća prije predaje.», тобто «До шістдесяти днів. Адміністративний збір сплачують перед поданням.».', (select id from public.lessons where id = 'dd6c5f39-f66e-5acb-8255-932f822ddcc5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('042843c5-2063-5533-8559-787f9268f946', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što biste voljeli raditi?', '["Можливо, бухгалтерією. Я б записалася на курс, щоб швидше знайти роботу.", "Так. Наприкінці складаєте кваліфікаційний іспит і отримуєте свідоцтво.", "Добрий день. В Україні я була вчителькою, але хотіла б змінити фах."]'::jsonb, 0, null, null, 'Darja: Dobar dan. U Ukrajini sam bila učiteljica, ali htjela bih promijeniti struku.
Savjetnik: Što biste voljeli raditi?
Darja: Možda knjigovodstvo. Upisala bih tečaj da bih brže našla posao.
Savjetnik: Knjigovođe su traženi. Možete dobiti vaučer za obrazovanje.
Darja: Je li tečaj onda besplatan?
Savjetnik: Jest. Na kraju polažete stručni ispit i dobivate uvjerenje.', 'Darja: Добрий день. В Україні я була вчителькою, але хотіла б змінити фах.
Savjetnik: Чим би ви хотіли займатися?
Darja: Можливо, бухгалтерією. Я б записалася на курс, щоб швидше знайти роботу.
Savjetnik: Бухгалтери затребувані. Ви можете отримати ваучер на навчання.
Darja: Тоді курс безкоштовний?
Savjetnik: Так. Наприкінці складаєте кваліфікаційний іспит і отримуєте свідоцтво.', 'Діалог «У консультанта»: «Što biste voljeli raditi?» — «Možda knjigovodstvo. Upisala bih tečaj da bih brže našla posao.», тобто «Можливо, бухгалтерією. Я б записалася на курс, щоб швидше знайти роботу.».', (select id from public.lessons where id = '24894494-1af7-5153-a7b0-7f0ef3c0bdce'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('4e67c421-7e24-5aac-bab7-86b91a630ba0', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Він хворів, у мене є довідка від лікаря». Що ви скажете?', null, '["Može li ostati u školi poslije nastave?", "Bio je bolestan, imam liječničku ispričnicu.", "Zanima me upis na diplomski studij."]'::jsonb, 1, null, null, null, null, '«Він хворів, у мене є довідка від лікаря.» — «Bio je bolestan, imam liječničku ispričnicu.».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('dc27650b-a220-5b77-b16c-909cae078a14', v_aid, 12, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Скільки коштує членський внесок?». Що ви скажете?', null, '["Kada završava prvo polugodište?", "Koliko iznosi članarina?", "Što treba priložiti zahtjevu?"]'::jsonb, 1, null, null, null, null, '«Скільки коштує членський внесок?» — «Koliko iznosi članarina?».', (select id from public.lessons where id = 'f0e24e2b-9e73-5a70-8f2f-ec825b0308e2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('6d547053-e238-5070-a9dd-fb63af941cc5', v_aid, 13, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «електронний щоденник (журнал)»', null, '[]'::jsonb, null, 'e-Dnevnik', null, null, null, '«електронний щоденник (журнал)» — e-Dnevnik.', (select id from public.lessons where id = '2a1b2b63-def1-5fb9-91e6-d09e1fd5b95c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('cd4f5076-dd57-535c-a15d-b692af64dffc', v_aid, 14, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Для безробітних курс безкоштовний.»', null, '["Za", "besplatan.", "je", "tečaj", "nezaposlene"]'::jsonb, null, 'Za nezaposlene je tečaj besplatan.', null, null, null, '«Для безробітних курс безкоштовний.» — «Za nezaposlene je tečaj besplatan.».', (select id from public.lessons where id = '24894494-1af7-5153-a7b0-7f0ef3c0bdce'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7affede8-9ee9-54db-b088-ba56e65eb050', v_aid, 15, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Він ходить до репетитора з математики.»', null, '["matematike", "ide", "Iz", "na", "instrukcije."]'::jsonb, null, 'Iz matematike ide na instrukcije.', null, null, null, '«Він ходить до репетитора з математики.» — «Iz matematike ide na instrukcije.».', (select id from public.lessons where id = 'f0e24e2b-9e73-5a70-8f2f-ec825b0308e2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('94575465-34fd-5f1f-ab6f-7f773297f2be', v_aid, 16, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я склала всі іспити!»', null, '[]'::jsonb, null, 'Položila sam sve ispite!', null, null, null, '«Я склала всі іспити!» — «Položila sam sve ispite!».', (select id from public.lessons where id = '4be96321-cd99-57ff-a9bc-17cfaf4f4c29'), 'PUBLISHED', 'claude_assessment_a2_v2');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, null, 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірка рівня A2 (програма A2 v2, схема 2026-11-07) — завдання з діалогів і вправ уроків A2. Потрібна перевірка носієм.');
