-- Перевірка модуля A2.3 · Модуль A2.3 — Моє минуле: дитинство й спогади · 12 завдань
do $$
declare v_aid uuid := '0ad30a29-aab4-5da6-9d15-8a922abe23ba';
begin
  if exists (select 1 from public.assessment_items where id = '65f0a6d8-ad84-5995-9fa7-ded233d0877d') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m03' and id <> v_aid) then
    raise exception 'Тест a2-m03 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m03', 'module', 'Перевірка модуля A2.3', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          '38b2ee69-f7d3-5de2-8208-b1fa31501558', 3, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('65f0a6d8-ad84-5995-9fa7-ded233d0877d', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У вас є діти?", "А коли ви одружилися?", "У що ви гралися?"]'::jsonb, 2, null, 'Što ste se igrali?', null, null, 'Прозвучало: «Što ste se igrali?» — «У що ви гралися?».', (select id from public.lessons where id = '65e0eec5-f830-5509-a807-db00ace41075'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('09c077da-cf8f-5b9f-bfcc-3d7f490a3976', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Кінотеатр знесли?", "Пілотом! А ти?", "Ти почувалася самотньою?"]'::jsonb, 0, null, 'Kino su srušili?', null, null, 'Прозвучало: «Kino su srušili?» — «Кінотеатр знесли?».', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('bd42459d-1c88-537b-a94f-92f76d866371', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Як вона вчила хорватську спочатку?', 'Kako sam našla posao', '["Ніяк не вчила", "Вчила слова й дивилася серіали", "Ходила на курси"]'::jsonb, 1, null, null, 'Kad sam došla u Hrvatsku, nisam znala ni riječ hrvatskog. Prva tri mjeseca bila su teška. Svaki dan sam učila nove riječi i gledala hrvatske serije s titlovima. Onda sam počela tražiti posao. Poslala sam životopis u deset hotela, ali nitko mi nije odgovorio. Jednog dana nazvala me voditeljica jednog malog hotela u Splitu i pozvala me na razgovor. Bila sam jako nervozna, ali sve je prošlo dobro. Razgovarale smo pola na hrvatskom, pola na engleskom. Sljedeći tjedan počela sam raditi na recepciji. Danas tamo radim već dvije godine i hrvatski mi više nije problem.', 'Коли я приїхала до Хорватії, я не знала жодного слова хорватською. Перші три місяці були важкими. Щодня я вчила нові слова й дивилася хорватські серіали із субтитрами. Потім я почала шукати роботу. Я надіслала резюме в десять готелів, але ніхто мені не відповів. Одного дня мені зателефонувала керівниця одного маленького готелю в Спліті й запросила мене на співбесіду. Я дуже хвилювалася, але все пройшло добре. Ми розмовляли наполовину хорватською, наполовину англійською. Наступного тижня я почала працювати на рецепції. Сьогодні я працюю там уже два роки, і хорватська для мене більше не проблема.', 'Текст «Як я знайшла роботу». Правильна відповідь: «Вчила слова й дивилася серіали».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('877a1ad7-5d02-52f5-8276-01c9ce6e5f3a', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što ste ponijeli sa sobom kad ste se selili?', '["Samo dva kofera. Spakirali smo dokumente, odjeću i fotografije.", "Volio bi igrati vaterpolo, ali članarina je skupa.", "Ulov dana je brancin. Može na žaru, s blitvom."]'::jsonb, 0, null, 'Što ste ponijeli sa sobom kad ste se selili?', null, null, 'Діалог «Дві валізи»: «Što ste ponijeli sa sobom kad ste se selili?» (Що ви взяли з собою, коли переїжджали?) — «Samo dva kofera. Spakirali smo dokumente, odjeću i fotografije.» (Лише дві валізи. Спакували документи, одяг і фотографії.).', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('38437355-2ccb-5105-90b8-2a3ede204021', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Sve ostalo ste ostavili iza sebe?', '["Položila sam! Dobila sam vrlo dobar.", "Jesmo. Ali nakon što smo našli stan, osjetila sam olakšanje.", "Učim sama godinu dana, ali moj izgovor je loš."]'::jsonb, 1, null, 'Sve ostalo ste ostavili iza sebe?', null, null, 'Діалог «Дві валізи»: «Sve ostalo ste ostavili iza sebe?» (А все інше залишили позаду?) — «Jesmo. Ali nakon što smo našli stan, osjetila sam olakšanje.» (Так. Але після того як ми знайшли квартиру, я відчула полегшення.).', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('72fcffcb-f7c9-5b2c-975a-7ed9cae9ab63', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imate li djece?', '["Imamo dvoje. Filip se rodio godinu dana kasnije.", "Ocjene se upisuju u e-Dnevnik, imat ćeš svoju lozinku.", "Do osamsto eura za četvero, ako je moguće."]'::jsonb, 0, null, 'Imate li djece?', null, null, 'Діалог «Дати мого життя»: «Imate li djece?» (У вас є діти?) — «Imamo dvoje. Filip se rodio godinu dana kasnije.» (Маємо двох. Філіп народився через рік.).', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('28b27164-0981-54ff-9338-05fbe4810f3f', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kino su srušili?', '["Подивись на цю чорно-білу фотографію. Це моя бабуся п’ятдесят років тому.", "У центрі нашого міста. Тоді тут був кінотеатр, а тепер торговий центр.", "Так, десять років тому. Місто дуже змінилося."]'::jsonb, 2, null, null, 'Darja: Vidi ovu crno-bijelu fotografiju. To je moja baka prije pedeset godina.
Daša: Kako je lijepa! A gdje je ovo?
Darja: U centru našeg grada. Tada je tu bilo kino, a sad je trgovački centar.
Daša: Kino su srušili?
Darja: Jesu, prije deset godina. Grad se jako promijenio.', 'Darja: Подивись на цю чорно-білу фотографію. Це моя бабуся п’ятдесят років тому.
Daša: Яка гарна! А де це?
Darja: У центрі нашого міста. Тоді тут був кінотеатр, а тепер торговий центр.
Daša: Кінотеатр знесли?
Darja: Так, десять років тому. Місто дуже змінилося.', 'Діалог «Старі фото»: «Kino su srušili?» — «Jesu, prije deset godina. Grad se jako promijenio.», тобто «Так, десять років тому. Місто дуже змінилося.».', (select id from public.lessons where id = 'b22c7dff-1657-5dad-94a6-5d059e346da8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e0be32b1-28fb-5b45-81f7-d0d415011241', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, kako su izgledali prvi mjeseci u Hrvatskoj?', '["Тепер я звикла. Я пишаюся всім, чого ми досягли.", "Спочатку так. Але щойно я записалася на курс, познайомилася з людьми.", "Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою."]'::jsonb, 2, null, null, 'Ivana: Darja, kako su izgledali prvi mjeseci u Hrvatskoj?
Darja: Teški. Nisam se znala snaći, a nedostajala mi je mama.
Ivana: Jesi li se osjećala usamljeno?
Darja: Na početku jesam. Ali čim sam upisala tečaj, upoznala sam ljude.
Ivana: A sad?
Darja: Sad sam se priviknula. Ponosna sam na sve što smo postigli.', 'Ivana: Дар’є, якими були перші місяці в Хорватії?
Darja: Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою.
Ivana: Ти почувалася самотньою?
Darja: Спочатку так. Але щойно я записалася на курс, познайомилася з людьми.
Ivana: А тепер?
Darja: Тепер я звикла. Я пишаюся всім, чого ми досягли.', 'Діалог «Перші місяці»: «Darja, kako su izgledali prvi mjeseci u Hrvatskoj?» — «Teški. Nisam se znala snaći, a nedostajala mi je mama.», тобто «Важкими. Я не знала, як дати собі раду, а ще сумувала за мамою.».', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('666d16f0-c1a7-5892-b4d1-4aca1dc88493', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я народилася п’ятого травня». Що ви скажете?', null, '["Rođena sam petog svibnja.", "Nikad neću zaboraviti taj dan.", "Htio bih paket aranžman za Krk."]'::jsonb, 0, null, null, null, null, '«Я народилася п’ятого травня.» — «Rođena sam petog svibnja.».', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b276fc18-1221-5e26-a082-80956c172a47', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «рости, дорослішати»', null, '[]'::jsonb, null, 'odrastati', null, null, null, '«рости, дорослішати» — odrastati.', (select id from public.lessons where id = '65e0eec5-f830-5509-a807-db00ace41075'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d3d32fdf-58ef-5619-9098-348a77008fdd', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ми заблукали в старому місті.»', null, '["starom", "se", "smo", "gradu.", "Izgubili", "u"]'::jsonb, null, 'Izgubili smo se u starom gradu.', null, null, null, '«Ми заблукали в старому місті.» — «Izgubili smo se u starom gradu.».', (select id from public.lessons where id = '6440a67e-bb4f-507e-ae20-ebf59c66424e'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('85852c96-717c-55e2-9c26-131c4d2dc19a', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «У дитинстві я боялася темряви.»', null, '[]'::jsonb, null, 'Kao dijete sam se bojala mraka.', null, null, null, '«У дитинстві я боялася темряви.» — «Kao dijete sam se bojala mraka.».', (select id from public.lessons where id = '65e0eec5-f830-5509-a807-db00ace41075'), 'PUBLISHED', 'claude_assessment_a2_v2');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, null, 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірка рівня A2 (програма A2 v2, схема 2026-11-07) — завдання з діалогів і вправ уроків A2. Потрібна перевірка носієм.');
