-- Перевірка модуля A2.4 · Модуль A2.4 — Люди й стосунки: характер, свята, конфлікти · 14 завдань
do $$
declare v_aid uuid := 'dcae59df-98df-56c9-9f94-63d9f1967064';
begin
  if exists (select 1 from public.assessment_items where id = '18bc081c-98c3-5b1d-bde8-8699e523b164') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m04' and id <> v_aid) then
    raise exception 'Тест a2-m04 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m04', 'module', 'Перевірка модуля A2.4', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          '8fad33b4-f461-5119-b5e5-f94b700e283c', 4, 0.70, 0.50, 7, 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('18bc081c-98c3-5b1d-bde8-8699e523b164', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ласкаво просимо на збори мешканців. У нас кілька скарг.", "Якщо тобі щось буде потрібно, дай мені знати.", "Дякую тобі. Це було довге й гарне життя."]'::jsonb, 0, null, 'Dobro došli na sastanak stanara. Imamo nekoliko pritužbi.', null, null, 'Прозвучало: «Dobro došli na sastanak stanara. Imamo nekoliko pritužbi.» — «Ласкаво просимо на збори мешканців. У нас кілька скарг.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f39aec5d-3d0b-54c3-8674-06eebbfc5112', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мені приємно. Усього найкращого тобі й родині!", "Тут багато хто святкує. Твоє привітання мене дуже потішило.", "Я наполегливий, але нетерплячий. Це моя вада."]'::jsonb, 0, null, 'Drago mi je. Sve najljepše tebi i obitelji!', null, null, 'Прозвучало: «Drago mi je. Sve najljepše tebi i obitelji!» — «Мені приємно. Усього найкращого тобі й родині!».', (select id from public.lessons where id = '75a84442-280d-56be-b746-81ca57caa0b5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('248490f4-6544-5c0e-851c-b2d8ec266778', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Наречена кидатиме букет. Давай, спробуй його спіймати!", "Іване, з іменинами! Бажаю тобі міцного здоров’я й щастя.", "І я б щось записав, щоб краще заробляти."]'::jsonb, 0, null, 'Mladenka će baciti buket. Hajde, probaj ga uhvatiti!', null, null, 'Прозвучало: «Mladenka će baciti buket. Hajde, probaj ga uhvatiti!» — «Наречена кидатиме букет. Давай, спробуй його спіймати!».', (select id from public.lessons where id = '68f2ada8-2352-5450-a073-72754ae0feb8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0ad4e1f1-5a58-525e-89d0-f77f8a500173', v_aid, 4, 'A2', 'reading', 'understand', 'multiple_choice', 'Куди Оксана запрошує Марію?', 'Nova susjeda', '["На вечерю в суботу", "На каву в неділю", "На прогулянку"]'::jsonb, 1, null, null, 'Marija: Dobar dan! Vi ste nova susjeda iz stana 5, zar ne?
Oksana: Da, dobar dan! Ja sam Oksana. Doselili smo se prošli tjedan.
Marija: Drago mi je! Ja sam Marija, živim ovdje već dvadeset godina. Kako vam se sviđa zgrada?
Oksana: Jako nam se sviđa, mirna je. Samo još ne znamo gdje se odvaja smeće.
Marija: Kante su iza zgrade, pokraj garaže. Ako vam nešto treba, slobodno pozvonite.
Oksana: Hvala vam puno! Dođite na kavu u nedjelju, ako imate vremena.
Marija: Rado ću doći!', 'Марія: Добрий день! Ви нова сусідка з квартири 5, правда?
Оксана: Так, добрий день! Я Оксана. Ми переїхали минулого тижня.
Марія: Приємно познайомитися! Я Марія, живу тут уже двадцять років. Як вам подобається будинок?
Оксана: Дуже подобається, він тихий. Тільки ми ще не знаємо, де сортують сміття.
Марія: Контейнери за будинком, біля гаража. Якщо вам щось потрібно, сміливо дзвоніть у двері.
Оксана: Щиро дякую! Приходьте на каву в неділю, якщо матимете час.
Марія: Із радістю прийду!', 'Текст «Нова сусідка». Правильна відповідь: «На каву в неділю».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('56a5b40e-438b-56ce-935d-396513291903', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li duhovit?', '["Jest, kad ga bolje upoznaš. Lako se slaže s ljudima.", "Jesu, prije deset godina. Grad se jako promijenio.", "Cijele dane smo bili vani: skrivača, lovice, ljuljačka iza kuće."]'::jsonb, 0, null, 'Je li duhovit?', null, null, 'Діалог «Новий колега»: «Je li duhovit?» (Він дотепний?) — «Jest, kad ga bolje upoznaš. Lako se slaže s ljudima.» (Так, коли краще його пізнаєш. Він легко ладнає з людьми.).', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1d06ecdc-fe2b-5011-af04-a8c4a630bee1', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li uvrijeđena?', '["Postoji. Traži se i poznavanje hrvatskog na razini B2.", "Jest. Ne javlja mi se dva dana.", "Pišu, učiteljica im provjeri zadaću. Ručak je u školskoj kuhinji."]'::jsonb, 1, null, 'Je li uvrijeđena?', null, null, 'Діалог «Сварка з сестрою»: «Je li uvrijeđena?» (Вона ображена?) — «Jest. Ne javlja mi se dva dana.» (Так. Не озивається до мене два дні.).', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0b3e0e23-2d13-51fb-82ed-9af8498f6716', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hvala, Dašo! Kako si znala?', '["Do šezdeset dana. Upravna pristojba se plaća prije predaje.", "Mi bismo htjeli neko mirno mjesto, bez velike gužve.", "Pisalo je u kalendaru. Kod nas se imendan rijetko slavi."]'::jsonb, 2, null, 'Hvala, Dašo! Kako si znala?', null, null, 'Діалог «Іменини»: «Hvala, Dašo! Kako si znala?» (Дякую, Дашо! Як ти знала?) — «Pisalo je u kalendaru. Kod nas se imendan rijetko slavi.» (Було написано в календарі. У нас іменини рідко святкують.).', (select id from public.lessons where id = '75a84442-280d-56be-b746-81ca57caa0b5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e159192b-52aa-5f92-b2f5-5ee189b6cc39', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kolege, predlažem da radimo od kuće petkom. Slažete li se?', '["А я аж ніяк не згоден. По п’ятницях у нас найбільше клієнтів.", "Середа — добрий компроміс.", "Безумовно, я з вами згодна."]'::jsonb, 2, null, null, 'Šef: Kolege, predlažem da radimo od kuće petkom. Slažete li se?
Daša: Svakako se slažem s Vama.
Marko: Ja se nikako ne slažem. Petkom imamo najviše klijenata.
Šef: U pravu ste, Marko. Što mislite o srijedi?
Marko: Srijeda je dobar kompromis.', 'Šef: Колеги, пропоную працювати з дому по п’ятницях. Ви згодні?
Daša: Безумовно, я з вами згодна.
Marko: А я аж ніяк не згоден. По п’ятницях у нас найбільше клієнтів.
Šef: Ви маєте рацію, Марку. Що думаєте про середу?
Marko: Середа — добрий компроміс.', 'Діалог «Нарада»: «Kolege, predlažem da radimo od kuće petkom. Slažete li se?» — «Svakako se slažem s Vama.», тобто «Безумовно, я з вами згодна.».', (select id from public.lessons where id = 'f029711f-710e-5327-be4d-2310435e6eac'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3861561f-3fa7-57cc-a781-a524333473dd', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Imate li račun i jamstveni list?', '["Тоді напишіть письмову скаргу. Строк відповіді — п’ятнадцять днів.", "Ми віддамо її в сервіс.", "Є. Ви продали її мені як нову, а вона не працює."]'::jsonb, 2, null, null, 'Darja: Dobar dan. Perilica koju sam kupila se pokvarila nakon mjesec dana.
Prodavač: Imate li račun i jamstveni list?
Darja: Imam. Prodali ste mi je kao novu, a ne radi.
Prodavač: Odnijet ćemo je u servis.
Darja: Ne slažem se. Zahtijevam novu perilicu ili povrat novca.
Prodavač: Onda napišite pisani prigovor. Rok za odgovor je petnaest dana.', 'Darja: Добрий день. Пральна машина, яку я купила, зламалася через місяць.
Prodavač: У вас є чек і гарантійний талон?
Darja: Є. Ви продали її мені як нову, а вона не працює.
Prodavač: Ми віддамо її в сервіс.
Darja: Я не згодна. Вимагаю нову пральну машину або повернення грошей.
Prodavač: Тоді напишіть письмову скаргу. Строк відповіді — п’ятнадцять днів.', 'Діалог «Зламана пральна машина»: «Imate li račun i jamstveni list?» — «Imam. Prodali ste mi je kao novu, a ne radi.», тобто «Є. Ви продали її мені як нову, а вона не працює.».', (select id from public.lessons where id = '2760a712-4fa2-56fd-b036-8427682ad804'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8aa0b1ba-4126-5c29-baaa-5e83abb8baec', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Ви припаркувалися на моє місце». Що ви скажете?', null, '["Parkirali ste se na moje mjesto.", "Oprosti mi, molim te.", "Perilica se pokvarila nakon mjesec dana."]'::jsonb, 0, null, null, null, null, '«Ви припаркувалися на моє місце.» — «Parkirali ste se na moje mjesto.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d395a120-45ec-5ece-afdf-6b5fbcbe222d', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Музика дуже гучна». Що ви скажете?', null, '["Grad se jako promijenio.", "Smiri se, razgovarajmo normalno.", "Glazba je jako glasna."]'::jsonb, 2, null, null, null, null, '«Музика дуже гучна.» — «Glazba je jako glasna.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('864c04d3-82b9-56ed-acaa-982a0c36ead2', v_aid, 12, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «позиція, ставлення»', null, '[]'::jsonb, null, 'stav', null, null, null, '«позиція, ставлення» — stav.', (select id from public.lessons where id = 'f029711f-710e-5327-be4d-2310435e6eac'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b169cf53-78e5-5e45-84df-6cdf9014d3db', v_aid, 13, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Вимагаю повернення грошей.»', null, '["novca.", "povrat", "Zahtijevam"]'::jsonb, null, 'Zahtijevam povrat novca.', null, null, null, '«Вимагаю повернення грошей.» — «Zahtijevam povrat novca.».', (select id from public.lessons where id = '2760a712-4fa2-56fd-b036-8427682ad804'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8affa2bd-c2be-5c80-ab34-b6c08ff50488', v_aid, 14, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я ціную щирих людей.»', null, '[]'::jsonb, null, 'Cijenim iskrene ljude.', null, null, null, '«Я ціную щирих людей.» — «Cijenim iskrene ljude.».', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_a2_v2');
