  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m05', 'module', 'Перевірка модуля A2.5', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          'aa10630b-c7e4-5d3a-b3dc-739e9eea9e06', 5, 0.70, 0.50, 7, 'Після модуля: 14 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~7 хв.')
