  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('72f7d58f-1866-55f6-898c-774dcfaf7114', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре. Я повідомлю вас, коли закрию лікарняний.", "Алло? Перепрошую, погано чути.", "Іду сьогодні. Мені відкриють лікарняний."]'::jsonb, 1, null, 'Halo? Oprostite, slabo se čuje.', null, null, 'Прозвучало: «Halo? Oprostite, slabo se čuje.» — «Алло? Перепрошую, погано чути.».', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('50adab1c-9e9e-5807-b1e9-a43ab4b6e5e0', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Мусите, і рахунок має бути фіскалізований.", "У компанії скорочення працівників. Звільнення з економічних причин.", "Спочатку обираєш вид діяльності й вписуєш обрт до реєстру."]'::jsonb, 2, null, 'Prvo odabereš djelatnost i upišeš obrt u obrtni registar.', null, null, 'Прозвучало: «Prvo odabereš djelatnost i upišeš obrt u obrtni registar.» — «Спочатку обираєш вид діяльності й вписуєш обрт до реєстру.».', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a9bc3e6b-13b2-5258-a8a9-43dda8ad02d7', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ми не встигаємо на два дні. Команда дуже перевантажена.", "Спитай у службі зайнятості про грант на самозайнятість.", "Звісно. Я скажу йому, щоб він вам передзвонив."]'::jsonb, 2, null, 'Naravno. Reći ću mu da Vam uzvrati poziv.', null, null, 'Прозвучало: «Naravno. Reći ću mu da Vam uzvrati poziv.» — «Звісно. Я скажу йому, щоб він вам передзвонив.».', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0c36d8e7-134e-503b-bf8e-af0930042384', v_aid, 4, 'A2', 'reading', 'understand', 'multiple_choice', 'Що він отримає наступного місяця?', 'Prvi tjedan na novom poslu', '["Нову квартиру", "Відпустку", "Договір на рік"]'::jsonb, 2, null, null, 'Danilo je prošli tjedan počeo raditi u velikom skladištu blizu Zagreba. Prvi dan mu je voditelj pokazao cijelo skladište i objasnio pravila. Radno vrijeme je od šest do dva, pa Danilo mora ustati u pet. Prva dva dana bila su teška: nije razumio sve što su kolege govorili, a bilo ga je sram pitati. Treći dan jedan kolega, Marko, ponudio mu je pomoć. Sada mu Marko polako objašnjava riječi koje ne zna. Danilo je zadovoljan: plaća je dobra, a kolege su ljubazni. Sljedeći mjesec dobit će ugovor na godinu dana.', 'Минулого тижня Данило почав працювати на великому складі біля Загреба. Першого дня керівник показав йому весь склад і пояснив правила. Робочий час — із шостої до другої, тому Данило мусить вставати о п’ятій. Перші два дні були важкими: він не розумів усього, що говорили колеги, а питати соромився. Третього дня один колега, Марко, запропонував йому допомогу. Тепер Марко повільно пояснює йому слова, яких він не знає. Данило задоволений: зарплата хороша, а колеги привітні. Наступного місяця він отримає договір на рік.', 'Текст «Перший тиждень на новій роботі». Правильна відповідь: «Договір на рік».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9f58d880-6916-543b-84fb-2a3470ca027b', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ivan je tada na godišnjem. Poklapa li se to?', '["Petsto eura, u tri rate. Upisujemo do petnaestog rujna.", "Djelomično. Mogla bih krenuti tjedan kasnije.", "Cijele dane smo bili vani: skrivača, lovice, ljuljačka iza kuće."]'::jsonb, 1, null, 'Ivan je tada na godišnjem. Poklapa li se to?', null, null, 'Діалог «Прошу відпустку»: «Ivan je tada na godišnjem. Poklapa li se to?» (Іван тоді у відпустці. Це збігається?) — «Djelomično. Mogla bih krenuti tjedan kasnije.» (Частково. Я могла б почати на тиждень пізніше.).', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('30c06654-e44d-546b-b36c-494e206db8b4', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebam li knjigovodstveni servis?', '["U Supetru. Vozači moraju sići do auta prije pristajanja.", "Pred Božić. Onda su zimski školski praznici.", "Preporučujem. Mi vodimo prihode, troškove i porez."]'::jsonb, 2, null, 'Trebam li knjigovodstveni servis?', null, null, 'Діалог «Розмова з бухгалтеркою»: «Trebam li knjigovodstveni servis?» (Мені потрібна бухгалтерська фірма?) — «Preporučujem. Mi vodimo prihode, troškove i porez.» (Раджу. Ми ведемо доходи, витрати й податок.).', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ad64471f-a31c-57fc-ba74-60f380d999fa', v_aid, 7, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Super. Tko će poslati kratak sažetak?', '["Ovjerena preslika diplome s apostilleom i prijepis ocjena, s prijevodom.", "Postoji. Traži se i poznavanje hrvatskog na razini B2.", "Ja ću ga poslati danas poslije podne."]'::jsonb, 2, null, 'Super. Tko će poslati kratak sažetak?', null, null, 'Діалог «Онлайн-нарада»: «Super. Tko će poslati kratak sažetak?» (Супер. Хто надішле коротке резюме?) — «Ja ću ga poslati danas poslije podne.» (Я надішлю його сьогодні після обіду.).', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e49440df-2db8-5aad-8556-4df509904ba9', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Čujete li me? Mogu li podijeliti zaslon?', '["Ось план на наступний тиждень. Пріоритет — новий клієнт.", "Чуємо. Прошу всіх інших вимкнути мікрофон.", "Я надішлю його сьогодні після обіду."]'::jsonb, 1, null, null, 'Daša: Čujete li me? Mogu li podijeliti zaslon?
Ivan: Čujemo. Molim sve ostale da isključe mikrofon.
Daša: Ovo je plan za sljedeći tjedan. Prioritet je novi klijent.
Ivan: Super. Tko će poslati kratak sažetak?
Daša: Ja ću ga poslati danas poslije podne.', 'Daša: Ви мене чуєте? Можу показати екран?
Ivan: Чуємо. Прошу всіх інших вимкнути мікрофон.
Daša: Ось план на наступний тиждень. Пріоритет — новий клієнт.
Ivan: Супер. Хто надішле коротке резюме?
Daša: Я надішлю його сьогодні після обіду.', 'Діалог «Онлайн-нарада»: «Čujete li me? Mogu li podijeliti zaslon?» — «Čujemo. Molim sve ostale da isključe mikrofon.», тобто «Чуємо. Прошу всіх інших вимкнути мікрофон.».', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e1c2ac2f-82b5-550a-b43c-f60d9c1f4a9c', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Žao mi je. Tražiš li novi posao?', '["Так. Новий роботодавець пропонує безстроковий договір. Це гарна нагода.", "Мій договір закінчується в червні, а мені його не продовжили.", "Шукала й знайшла! Я отримала пропозицію в Спліті."]'::jsonb, 2, null, null, 'Daša: Ugovor mi ističe u lipnju, a nisu mi ga produžili.
Ivan: Žao mi je. Tražiš li novi posao?
Daša: Tražila sam i našla sam! Dobila sam ponudu u Splitu.
Ivan: Odlično! Hoćeš li prihvatiti ponudu?
Daša: Hoću. Novi poslodavac nudi ugovor na neodređeno. To je dobra prilika.', 'Daša: Мій договір закінчується в червні, а мені його не продовжили.
Ivan: Мені шкода. Ти шукаєш нову роботу?
Daša: Шукала й знайшла! Я отримала пропозицію в Спліті.
Ivan: Чудово! Приймеш пропозицію?
Daša: Так. Новий роботодавець пропонує безстроковий договір. Це гарна нагода.', 'Діалог «Нова пропозиція»: «Žao mi je. Tražiš li novi posao?» — «Tražila sam i našla sam! Dobila sam ponudu u Splitu.», тобто «Шукала й знайшла! Я отримала пропозицію в Спліті.».', (select id from public.lessons where id = '3ceb812b-6a68-5204-beba-52e0cb3031ad'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3da26aa5-9f0d-5c8c-b3a0-debfba482a76', v_aid, 10, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Повідомляю, що захворіла». Що ви скажете?', null, '["Mogu li razgovarati s gospođom Babić?", "Ispričavam se zbog kašnjenja.", "Javljam se bolesna."]'::jsonb, 2, null, null, null, null, '«Повідомляю, що захворіла.» — «Javljam se bolesna.».', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('30f42aab-132a-5db2-80e6-394cc50f1ca7', v_aid, 11, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мене звільнили». Що ви скажете?', null, '["Dobio sam otkaz.", "Ovaj tjedan sam jako opterećena.", "Imate li slobodan stol uz more?"]'::jsonb, 0, null, null, null, null, '«Мене звільнили.» — «Dobio sam otkaz.».', (select id from public.lessons where id = '3ceb812b-6a68-5204-beba-52e0cb3031ad'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e255a369-d79d-5cde-b87b-9e4a13532429', v_aid, 12, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «у вкладенні»', null, '[]'::jsonb, null, 'u privitku', null, null, null, '«у вкладенні» — u privitku.', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9b2fd4fe-1f35-5908-ab31-7dcdf7226ac7', v_aid, 13, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Кожному покупцеві треба виписати рахунок.»', null, '["račun.", "kupcu", "izdati", "Svakom", "treba"]'::jsonb, null, 'Svakom kupcu treba izdati račun.', null, null, null, '«Кожному покупцеві треба виписати рахунок.» — «Svakom kupcu treba izdati račun.».', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0b6480c6-c61a-5409-9643-3dddb014b262', v_aid, 14, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Чи можемо перенести строк?»', null, '[]'::jsonb, null, 'Možemo li pomaknuti rok?', null, null, null, '«Чи можемо перенести строк?» — «Možemo li pomaknuti rok?».', (select id from public.lessons where id = '97f1ba90-fe04-5907-803f-2ec0854b0a09'), 'PUBLISHED', 'claude_assessment_a2_v2');
