-- Перевірка модуля A2.6 · Модуль A2.6 — Установи, послуги й гроші · 12 завдань
do $$
declare v_aid uuid := 'f80d69f0-8504-5be2-97f7-d834daa89d58';
begin
  if exists (select 1 from public.assessment_items where id = 'cd2f4a18-e31b-57ca-ab52-68f6d7b9009c') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m06' and id <> v_aid) then
    raise exception 'Тест a2-m06 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m06', 'module', 'Перевірка модуля A2.6', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          'f811eff6-8d8a-5fac-8ae7-6b78020976f1', 6, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('cd2f4a18-e31b-57ca-ab52-68f6d7b9009c', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Заплатімо одразу, інакше нараховують пеню.", "Так, на стрижку о десятій. Просто трохи підрівняйте.", "Буде. Наприкінці написано «засвідчено», з печаткою й підписом."]'::jsonb, 0, null, 'Platimo ga odmah, inače se plaćaju kamate.', null, null, 'Прозвучало: «Platimo ga odmah, inače se plaćaju kamate.» — «Заплатімо одразу, інакше нараховують пеню.».', (select id from public.lessons where id = '5f9af92b-06e1-5179-81a3-19625a5b8273'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7d138146-c940-5f5e-aa74-3885dc390706', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А якщо заяву відхилять?", "Скільки триває страхова виплата?", "Яка орієнтовна вартість усієї роботи?"]'::jsonb, 0, null, 'A ako zahtjev bude odbijen?', null, null, 'Прозвучало: «A ako zahtjev bude odbijen?» — «А якщо заяву відхилять?».', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('755ceeb3-b725-5583-83a2-e234193883d5', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Коли можна зателефонувати?', 'Nedostaje dokument', '["У робочі дні з 8 до 12", "Тільки в суботу", "Щодня до 20"]'::jsonb, 0, null, null, 'Poštovani gospodine Melnyk,
primili smo vaš zahtjev za produženje boravka. Nažalost, zahtjev nije potpun: nedostaje potvrda o zdravstvenom osiguranju. Molimo vas da je donesete osobno ili pošaljete poštom najkasnije do 30. listopada. Ako dokument ne dobijemo na vrijeme, nećemo moći riješiti vaš zahtjev. Ako imate pitanja, možete nas nazvati radnim danom od 8 do 12 sati.
Hvala na razumijevanju.
S poštovanjem,
Ured za strance', 'Шановний пане Мельник!
Ми отримали вашу заяву про продовження перебування. На жаль, заява неповна: бракує підтвердження медичного страхування. Просимо принести його особисто або надіслати поштою не пізніше 30 жовтня. Якщо ми не отримаємо документ вчасно, ми не зможемо розглянути вашу заяву. Якщо у вас є запитання, можете зателефонувати нам у робочі дні з 8 до 12 години.
Дякуємо за розуміння.
З повагою,
Відділ для іноземців', 'Текст «У заяві бракує документа». Правильна відповідь: «У робочі дні з 8 до 12».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b1c15a6a-77f9-55fe-a031-9cf66cc78f8e', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu li ovdje ovjeriti presliku diplome?', '["Možete, ako imate original.", "Ocjene se upisuju u e-Dnevnik, imat ćeš svoju lozinku.", "U Supetru. Vozači moraju sići do auta prije pristajanja."]'::jsonb, 0, null, 'Mogu li ovdje ovjeriti presliku diplome?', null, null, 'Діалог «Копія диплома»: «Mogu li ovdje ovjeriti presliku diplome?» (Чи можу я тут засвідчити копію диплома?) — «Možete, ako imate original.» (Можете, якщо маєте оригінал.).', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('33d01048-3f61-59c3-ac66-7825d7a734b4', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan! Jeste li naručeni?', '["Mi bismo htjeli neko mirno mjesto, bez velike gužve.", "Medicinska sestra je regulirana profesija, pa treba stručno priznavanje.", "Jesam, za šišanje u deset. Samo me malo podšišajte."]'::jsonb, 2, null, 'Dobar dan! Jeste li naručeni?', null, null, 'Діалог «У перукарні»: «Dobar dan! Jeste li naručeni?» (Добрий день! Ви записані?) — «Jesam, za šišanje u deset. Samo me malo podšišajte.» (Так, на стрижку о десятій. Просто трохи підрівняйте.).', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d8f8278e-b592-51b4-8194-38e416e99f88', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan, na kaputu je mrlja od vina. Možete li je skinuti?', '["Probat ćemo. Kaput će biti gotov do petka.", "Obično omotnica s novcem. Takav je običaj.", "Ovisi o prihodu. Napravimo zajedno poslovni plan."]'::jsonb, 0, null, 'Dobar dan, na kaputu je mrlja od vina. Možete li je skinuti?', null, null, 'Діалог «Хімчистка й кравець»: «Dobar dan, na kaputu je mrlja od vina. Možete li je skinuti?» (Добрий день, на пальті пляма від вина. Можете її вивести?) — «Probat ćemo. Kaput će biti gotov do petka.» (Спробуємо. Пальто буде готове до п’ятниці.).', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f71f7e78-0bef-5333-8db7-7c8849c60c7b', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Možete li mi poslati predračun?', '["Близько ста євро, але матеріали не включено.", "Можу прийти завтра. Виїзд — двадцять євро.", "Звісно. Домовмося на завтра на дев’яту."]'::jsonb, 2, null, null, 'Darja: Dobar dan, trebam majstora. Slavina kapa, a začepio se i odvod.
Majstor: Mogu doći sutra. Izlazak na teren je dvadeset eura.
Darja: Kolika je procjena za cijeli posao?
Majstor: Oko sto eura, ali materijal nije uključen.
Darja: Možete li mi poslati predračun?
Majstor: Naravno. Dogovorimo termin za sutra u devet.', 'Darja: Добрий день, мені потрібен майстер. Кран капає, а ще засмітився злив.
Majstor: Можу прийти завтра. Виїзд — двадцять євро.
Darja: Яка орієнтовна вартість усієї роботи?
Majstor: Близько ста євро, але матеріали не включено.
Darja: Можете надіслати мені кошторис?
Majstor: Звісно. Домовмося на завтра на дев’яту.', 'Діалог «Тече кран»: «Možete li mi poslati predračun?» — «Naravno. Dogovorimo termin za sutra u devet.», тобто «Звісно. Домовмося на завтра на дев’яту.».', (select id from public.lessons where id = 'bf43b6bd-d547-596b-8981-55a4043cf238'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d94df79a-ba43-5529-b7cc-0a523a103f8d', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'I na kraju „u prilogu“ i dokumenti?', '["Точно. І не забудь підпис.", "«Заява про видачу довідки». Потім: «Цим листом прошу видати…»", "Угорі напиши свої дані, а нижче — кому адресовано: міському відділу."]'::jsonb, 0, null, null, 'Darja: Ivana, kako da napišem zahtjev za potvrdu o prebivalištu?
Ivana: Gore napiši svoje podatke, a ispod naslovljeno na Gradski ured.
Darja: A što piše u predmetu?
Ivana: „Zahtjev za izdavanje potvrde.“ Onda: „Ovim putem molim izdavanje…“
Darja: I na kraju „u prilogu“ i dokumenti?
Ivana: Točno. I ne zaboravi potpis.', 'Darja: Івано, як мені написати заяву на довідку про місце проживання?
Ivana: Угорі напиши свої дані, а нижче — кому адресовано: міському відділу.
Darja: А що писати в темі?
Ivana: «Заява про видачу довідки». Потім: «Цим листом прошу видати…»
Darja: А наприкінці «у додатку» і документи?
Ivana: Точно. І не забудь підпис.', 'Діалог «Як написати заяву?»: «I na kraju „u prilogu“ i dokumenti?» — «Točno. I ne zaboravi potpis.», тобто «Точно. І не забудь підпис.».', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d5a52e44-55fb-5763-a774-a484790c2f5c', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Чи можете засвідчити мій підпис?». Що ви скажете?', null, '["Možete li ovjeriti moj potpis?", "Koji ured je nadležan za to?", "Trebam punomoć za sestru."]'::jsonb, 0, null, null, null, null, '«Чи можете засвідчити мій підпис?» — «Možete li ovjeriti moj potpis?».', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f7dcc506-3e45-5016-a0ee-f84bf1d55e69', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «довіреність»', null, '[]'::jsonb, null, 'punomoć', null, null, null, '«довіреність» — punomoć.', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d40fe759-3288-5a5e-a68a-31bdfe11e9e3', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Кран капає всю ніч.»', null, '["noć.", "kapa", "cijelu", "Slavina"]'::jsonb, null, 'Slavina kapa cijelu noć.', null, null, null, '«Кран капає всю ніч.» — «Slavina kapa cijelu noć.».', (select id from public.lessons where id = 'bf43b6bd-d547-596b-8981-55a4043cf238'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('88843519-0927-51cb-b80b-b5fb85b3c14f', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я хочу заявити про збиток.»', null, '[]'::jsonb, null, 'Želim prijaviti štetu.', null, null, null, '«Я хочу заявити про збиток.» — «Želim prijaviti štetu.».', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_a2_v2');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, null, 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірка рівня A2 (програма A2 v2, схема 2026-11-07) — завдання з діалогів і вправ уроків A2. Потрібна перевірка носієм.');
end $$;

-- Перевірка модуля A2.7 · Модуль A2.7 — Здоров’я: система й самопочуття · 12 завдань
do $$
