begin
  if exists (select 1 from public.assessment_items where id = '14081c91-0d7c-54ad-942b-8696788f7a7c') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m07' and id <> v_aid) then
    raise exception 'Тест a2-m07 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m07', 'module', 'Перевірка модуля A2.7', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          'd66361ac-89bc-5021-99ad-c3f61c71145c', 7, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('14081c91-0d7c-54ad-942b-8696788f7a7c', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добрий день, у мене огляд о дев’ятій.", "Це схоже на професійне вигорання. Тобі треба відновити сили.", "Мені потрібен лікарняний по догляду за дитиною. Я працюю в магазині."]'::jsonb, 2, null, 'Trebam bolovanje radi njege djeteta. Radim u trgovini.', null, null, 'Прозвучало: «Trebam bolovanje radi njege djeteta. Radim u trgovini.» — «Мені потрібен лікарняний по догляду за дитиною. Я працюю в магазині.».', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('2242f8da-1ee8-5936-990a-111137d5af45', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Чудово. Ви регулярно приймаєте таблетки?", "Скільки чекати на огляд у фахівця?", "Мої результати вже прийшли?"]'::jsonb, 0, null, 'Odlično. Uzimate li tablete redovito?', null, null, 'Прозвучало: «Odlično. Uzimate li tablete redovito?» — «Чудово. Ви регулярно приймаєте таблетки?».', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f7a4d92f-7b3e-5f5d-aeaa-c4b98f638109', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Коли треба мити руки?', 'Kako ne biti bolestan zimi', '["Раз на тиждень", "Після транспорту й перед їжею", "Тільки вранці"]'::jsonb, 1, null, null, 'Zimi je puno ljudi prehlađeno. Liječnici kažu da je najvažnije često prati ruke, osobito poslije javnog prijevoza i prije jela. Trebamo piti dovoljno vode i jesti puno voća i povrća. Dobro je svaki dan šetati na svježem zraku, čak i kad je hladno. Spavajte najmanje sedam sati. Ako ste bolesni, ostanite kod kuće i ne idite na posao ili u školu, jer tako možete zaraziti druge. Ako imate visoku temperaturu dulje od tri dana, javite se svom liječniku.', 'Узимку багато людей застуджені. Лікарі кажуть, що найважливіше — часто мити руки, особливо після громадського транспорту й перед їжею. Треба пити достатньо води й їсти багато фруктів і овочів. Добре щодня гуляти на свіжому повітрі, навіть коли холодно. Спіть щонайменше сім годин. Якщо ви хворі, залишайтеся вдома й не йдіть на роботу чи до школи, бо так можна заразити інших. Якщо висока температура тримається довше трьох днів, зверніться до свого лікаря.', 'Текст «Як не захворіти взимку». Правильна відповідь: «Після транспорту й перед їжею».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ddc45710-6197-518e-a247-9c0145e7eb33', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Joj! Jesi li ležao u bolnici?', '["Ocjene se upisuju u e-Dnevnik, imat ćeš svoju lozinku.", "Napiši „Poštovani gospodine Horvat“, ne „Bok“.", "Tjedan dana. Primili su me zbog visoke temperature."]'::jsonb, 2, null, 'Joj! Jesi li ležao u bolnici?', null, null, 'Діалог «Запалення легень»: «Joj! Jesi li ležao u bolnici?» (Ой! Ти лежав у лікарні?) — «Tjedan dana. Primili su me zbog visoke temperature.» (Тиждень. Мене поклали через високу температуру.).', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('45eb41b3-5a0a-5b7f-a912-b283555183a6', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koliko se čeka na specijalistički pregled?', '["Morate, i račun mora biti fiskaliziran.", "Pisalo je u kalendaru. Kod nas se imendan rijetko slavi.", "Oko dva mjeseca. Ako ne želite čekati, postoji privatna poliklinika."]'::jsonb, 2, null, 'Koliko se čeka na specijalistički pregled?', null, null, 'Діалог «Направлення»: «Koliko se čeka na specijalistički pregled?» (Скільки чекати на огляд у фахівця?) — «Oko dva mjeseca. Ako ne želite čekati, postoji privatna poliklinika.» (Близько двох місяців. Якщо не хочете чекати, є приватна поліклініка.).', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('cfa101e0-9479-5104-9417-6cc70657af1a', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što ti je s rukom?', '["Samo dva kofera. Spakirali smo dokumente, odjeću i fotografije.", "Oko sto eura, ali materijal nije uključen.", "Slomila sam je na skijanju prošli mjesec."]'::jsonb, 2, null, 'Što ti je s rukom?', null, null, 'Діалог «Зламана рука»: «Što ti je s rukom?» (Що в тебе з рукою?) — «Slomila sam je na skijanju prošli mjesec.» (Я зламала її на лижах минулого місяця.).', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('bc46d45d-0a03-5c24-a64d-2532476c9bc8', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Trebam li prije toga napraviti nalaze krvi?', '["Так. Забір крові — уранці, приходьте натщесерце.", "Близько двох місяців. Якщо не хочете чекати, є приватна поліклініка.", "Я дам вам електронне направлення до невролога."]'::jsonb, 0, null, null, 'Darja: Dobar dan, doktorice. Već tjedan dana osjećam trnce u ruci.
Liječnica: Dat ću Vam e-uputnicu za neurologa.
Darja: Koliko se čeka na specijalistički pregled?
Liječnica: Oko dva mjeseca. Ako ne želite čekati, postoji privatna poliklinika.
Darja: Trebam li prije toga napraviti nalaze krvi?
Liječnica: Da. Vađenje krvi je ujutro, dođite natašte.', 'Darja: Добрий день, пані лікарко. Уже тиждень я відчуваю поколювання в руці.
Liječnica: Я дам вам електронне направлення до невролога.
Darja: Скільки чекати на огляд у фахівця?
Liječnica: Близько двох місяців. Якщо не хочете чекати, є приватна поліклініка.
Darja: Мені треба перед тим здати аналізи крові?
Liječnica: Так. Забір крові — уранці, приходьте натщесерце.', 'Діалог «Направлення»: «Trebam li prije toga napraviti nalaze krvi?» — «Da. Vađenje krvi je ujutro, dođite natašte.», тобто «Так. Забір крові — уранці, приходьте натщесерце.».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('83469f7c-cc98-5412-a43a-3fe946206fa2', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako je tlak ovaj mjesec?', '["Одного разу пропустив дозу, забув.", "Так не можна. Я дам вам рецепт на повторні видачі, і їжте менше солі.", "Уранці вищий, увечері нижчий. Я веду щоденник тиску."]'::jsonb, 2, null, null, 'Liječnica: Kako je tlak ovaj mjesec?
Ivan: Ujutro je viši, navečer je niži. Vodim dnevnik tlaka.
Liječnica: Odlično. Uzimate li tablete redovito?
Ivan: Jednom sam preskočio dozu, zaboravio sam.
Liječnica: To ne smijete. Dat ću Vam ponovljivi recept, i jedite manje soli.', 'Liječnica: Який тиск цього місяця?
Ivan: Уранці вищий, увечері нижчий. Я веду щоденник тиску.
Liječnica: Чудово. Ви регулярно приймаєте таблетки?
Ivan: Одного разу пропустив дозу, забув.
Liječnica: Так не можна. Я дам вам рецепт на повторні видачі, і їжте менше солі.', 'Діалог «Мій тиск»: «Kako je tlak ovaj mjesec?» — «Ujutro je viši, navečer je niži. Vodim dnevnik tlaka.», тобто «Уранці вищий, увечері нижчий. Я веду щоденник тиску.».', (select id from public.lessons where id = 'd295953d-21df-54ec-9b99-7aa7b872acca'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('dfce20a8-6cd4-52ab-a648-1b98e9d612fa', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мені потрібне направлення до кардіолога». Що ви скажете?', null, '["Trebam uputnicu za kardiologa.", "Trebam jači lijek protiv bolova.", "Nakon tri tjedna opet sam na nogama."]'::jsonb, 0, null, null, null, null, '«Мені потрібне направлення до кардіолога.» — «Trebam uputnicu za kardiologa.».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('10863a68-2d29-594f-a758-edbbc86199ef', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «невролог»', null, '[]'::jsonb, null, 'neurolog', null, null, null, '«невролог» — neurolog.', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b3b5ea28-a898-58b6-8a52-191faea836b3', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Приходьте на огляд натщесерце.»', null, '["pregled", "Na", "natašte.", "dođite"]'::jsonb, null, 'Na pregled dođite natašte.', null, null, null, '«Приходьте на огляд натщесерце.» — «Na pregled dođite natašte.».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b24bf7b0-7272-5e39-ae25-9d80f2cf0fc3', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я постійно в стресі.»', null, '[]'::jsonb, null, 'Stalno sam pod stresom.', null, null, null, '«Я постійно в стресі.» — «Stalno sam pod stresom.».', (select id from public.lessons where id = '4b8782ab-0559-531b-a393-38aaf599a97c'), 'PUBLISHED', 'claude_assessment_a2_v2');
