-- Перевірка модуля A2.8 · Модуль A2.8 — Авто в Хорватії · 12 завдань
do $$
declare v_aid uuid := '16ee4ea2-2be0-589e-8b43-687838c49acd';
begin
  if exists (select 1 from public.assessment_items where id = 'c86505ed-8370-5ee9-a615-d2ebb6cb4e69') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m08' and id <> v_aid) then
