  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m08', 'module', 'Перевірка модуля A2.8', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          'f72289b9-a174-5dd1-8cf6-553684bd120d', 8, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('c86505ed-8370-5ee9-a615-d2ebb6cb4e69', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Домовилися. Переоформлення робимо в п’ятницю.", "Ваша правда. Заповнімо європротокол.", "На жаль, авто не пройшло. Гальма зношені."]'::jsonb, 1, null, 'Imate pravo. Ispunimo europsko izvješće.', null, null, 'Прозвучало: «Imate pravo. Ispunimo europsko izvješće.» — «Ваша правда. Заповнімо європротокол.».', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('912bc3e1-2568-5359-8148-c68ca61660af', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Не мусите. Фото на документи роблять тут.", "Трохи, нічого страшного.", "Радар вас зафіксував. Це правопорушення."]'::jsonb, 2, null, 'Radar Vas je snimio. To je prekršaj.', null, null, 'Прозвучало: «Radar Vas je snimio. To je prekršaj.» — «Радар вас зафіксував. Це правопорушення.».', (select id from public.lessons where id = 'dfa42285-bd22-5df8-bf4a-670f56911803'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('2b071b25-a55c-512a-834a-4126673460ca', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Усе в порядку?", "Вам потрібне свідоцтво про реєстрацію?", "Ви в порядку? Ніхто не постраждав?"]'::jsonb, 1, null, 'Trebate li prometnu dozvolu?', null, null, 'Прозвучало: «Trebate li prometnu dozvolu?» — «Вам потрібне свідоцтво про реєстрацію?».', (select id from public.lessons where id = 'c689f4db-1707-535b-a2cd-0f244b663854'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a10143ea-cf77-5882-99e9-271005982e4d', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li svjedoka?', '["Ima, ova gospođa je sve vidjela.", "Ujutro je viši, navečer je niži. Vodim dnevnik tlaka.", "Hoće. Na kraju piše „ovjereno“, s pečatom i potpisom."]'::jsonb, 0, null, 'Ima li svjedoka?', null, null, 'Діалог «Розмова з поліцією»: «Ima li svjedoka?» (Є свідки?) — «Ima, ova gospođa je sve vidjela.» (Є, ця пані все бачила.).', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ca2707db-4f17-563e-a5e0-8f5c9e5a03b9', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li bio na žutoj crti?', '["Morate, i račun mora biti fiskaliziran.", "Možda djelomično, na pločniku.", "Srijeda je dobar kompromis."]'::jsonb, 1, null, 'Je li bio na žutoj crti?', null, null, 'Діалог «Де моє авто?»: «Je li bio na žutoj crti?» (Воно стояло на жовтій лінії?) — «Možda djelomično, na pločniku.» (Можливо, частково, на тротуарі.).', (select id from public.lessons where id = 'dfa42285-bd22-5df8-bf4a-670f56911803'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('30bd0bcd-4323-5da7-91fe-bec5eac75adc', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Joj, zastoj! Možemo li ga zaobići?', '["Oko dva mjeseca. Ako ne želite čekati, postoji privatna poliklinika.", "Samo dva kofera. Spakirali smo dokumente, odjeću i fotografije.", "Možemo. Siđimo s autoceste na sljedećem izlazu."]'::jsonb, 2, null, 'Joj, zastoj! Možemo li ga zaobići?', null, null, 'Діалог «Затор»: «Joj, zastoj! Možemo li ga zaobići?» (Ой, затор! Можемо його об’їхати?) — «Možemo. Siđimo s autoceste na sljedećem izlazu.» (Можемо. З’їдьмо з автостради на наступному з’їзді.).', (select id from public.lessons where id = '161ebc1e-5359-551e-82a5-ddd878ceb97a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8c81d449-c1ca-599a-9abb-bd18edf38122', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li auto ikad bio udaren?', '["Я перший власник, і в мене всі рахунки із сервісу.", "Так. Рік випуску дві тисячі шістнадцятий, сто двадцять тисяч кілометрів.", "Ні. Приїжджайте й проїдьтеся."]'::jsonb, 2, null, null, 'Darja: Dobar dan, zovem zbog oglasa za auto. Je li još na prodaju?
Prodavač: Jest. Godište je dvije tisuće šesnaest, sto dvadeset tisuća kilometara.
Darja: Jeste li prvi vlasnik? Imate li servisnu knjižicu?
Prodavač: Prvi sam vlasnik i imam sve račune iz servisa.
Darja: Je li auto ikad bio udaren?
Prodavač: Nije. Dođite pa se provozajte.', 'Darja: Добрий день, дзвоню щодо оголошення про авто. Воно ще продається?
Prodavač: Так. Рік випуску дві тисячі шістнадцятий, сто двадцять тисяч кілометрів.
Darja: Ви перший власник? У вас є сервісна книжка?
Prodavač: Я перший власник, і в мене всі рахунки із сервісу.
Darja: Авто колись було бите?
Prodavač: Ні. Приїжджайте й проїдьтеся.', 'Діалог «Дзвінок за оголошенням»: «Je li auto ikad bio udaren?» — «Nije. Dođite pa se provozajte.», тобто «Ні. Приїжджайте й проїдьтеся.».', (select id from public.lessons where id = '6a010148-5c1c-5e64-ab4a-c030b3adb969'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8f8f1ae3-5d6f-537c-a77d-d440c7227d1e', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jeste li dobro? Nitko nije ozlijeđen?', '["Я в порядку. Вибачте, я вас не бачив.", "Добре. Спочатку поставлю знак аварійної зупинки й сфотографую пошкодження.", "Ви не надали мені переваги й вдарили мене в двері."]'::jsonb, 0, null, null, 'Darja: Jeste li dobro? Nitko nije ozlijeđen?
Vozač: Dobro sam. Oprostite, nisam Vas vidio.
Darja: Oduzeli ste mi prednost i udarili me u vrata.
Vozač: Imate pravo. Ispunimo europsko izvješće.
Darja: Dobro. Prvo ću postaviti sigurnosni trokut i fotografirati štetu.', 'Darja: Ви в порядку? Ніхто не постраждав?
Vozač: Я в порядку. Вибачте, я вас не бачив.
Darja: Ви не надали мені переваги й вдарили мене в двері.
Vozač: Ваша правда. Заповнімо європротокол.
Darja: Добре. Спочатку поставлю знак аварійної зупинки й сфотографую пошкодження.', 'Діалог «На перехресті»: «Jeste li dobro? Nitko nije ozlijeđen?» — «Dobro sam. Oprostite, nisam Vas vidio.», тобто «Я в порядку. Вибачте, я вас не бачив.».', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('de7959a9-36c1-5ba4-9258-fecbd9ccf224', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Коли я можу забрати документ?». Що ви скажете?', null, '["Kada mogu podići dokument?", "Nisam vidio znak.", "Rođena sam petog svibnja."]'::jsonb, 0, null, null, null, null, '«Коли я можу забрати документ?» — «Kada mogu podići dokument?».', (select id from public.lessons where id = 'd4af6240-036d-5046-9c4a-430b34a04c79'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('dd3763c8-a2e1-524f-aa3f-176c01849114', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «вм’ятий»', null, '[]'::jsonb, null, 'udubljen', null, null, null, '«вм’ятий» — udubljen.', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('edf4c8ba-3acc-5046-a79b-5878f9412f25', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Паркування можна оплатити SMS-кою.»', null, '["možete", "platiti", "Parking", "SMS-om."]'::jsonb, null, 'Parking možete platiti SMS-om.', null, null, null, '«Паркування можна оплатити SMS-кою.» — «Parking možete platiti SMS-om.».', (select id from public.lessons where id = 'dfa42285-bd22-5df8-bf4a-670f56911803'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('55139d22-07ab-513f-8961-3aa501fe2ce8', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Як оплачують проїзд по автостраді?»', null, '[]'::jsonb, null, 'Kako se plaća cestarina?', null, null, null, '«Як оплачують проїзд по автостраді?» — «Kako se plaća cestarina?».', (select id from public.lessons where id = '161ebc1e-5359-551e-82a5-ddd878ceb97a'), 'PUBLISHED', 'claude_assessment_a2_v2');
