  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('53aadf61-a9e2-5271-932a-4160a64ebdea', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Канадери вже тут. Пожежники гасять з ранку.", "Молодець. Потроху захищаємо довкілля.", "А діти хочуть на пляж..."]'::jsonb, 2, null, 'A djeca žele na plažu...', null, null, 'Прозвучало: «A djeca žele na plažu...» — «А діти хочуть на пляж...».', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3bc4a7c2-e5e3-56be-9807-9bdd620d35c0', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Дар’є, у суботу акція з прибирання пляжу. Підеш?", "Сусідко, куди йде ця пластикова пляшка?", "Дашо, куди викидаємо залишки їжі?"]'::jsonb, 1, null, 'Susjedo, kamo ide ova plastična boca?', null, null, 'Прозвучало: «Susjedo, kamo ide ova plastična boca?» — «Сусідко, куди йде ця пластикова пляшка?».', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d924e7ea-ef16-5e8e-9c20-2cf39ae2c141', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Що сталося у ванній?', 'Problem u stanu', '["Зламалися двері", "Не горить світло", "Тече вода з труби"]'::jsonb, 2, null, null, 'Poštovani gospodine Horvat,
javljam vam se jer već tri dana u kupaonici curi voda iz cijevi ispod umivaonika. Pokušala sam sama zatvoriti ventil, ali voda i dalje curi. Pod je stalno mokar i bojim se da će se oštetiti stan ispod nas. Osim toga, perilica rublja ne radi od prošle subote. Molim vas da što prije pošaljete majstora. Kod kuće sam svaki dan poslije 16 sati, a u subotu cijeli dan.
Unaprijed hvala.
Lijep pozdrav,
Olena Kovalenko', 'Шановний пане Горват!
Пишу вам, бо вже три дні у ванній тече вода з труби під умивальником. Я пробувала сама закрити вентиль, але вода й далі тече. Підлога весь час мокра, і я боюся, що пошкодиться квартира під нами. Крім того, пральна машина не працює з минулої суботи. Прошу якомога швидше надіслати майстра. Я вдома щодня після 16 години, а в суботу — цілий день.
Заздалегідь дякую.
З повагою,
Олена Коваленко', 'Текст «Проблема в квартирі». Правильна відповідь: «Тече вода з труби».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f1d05b95-d64d-5ab5-9420-e5816c824b22', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoće li evakuirati kamp?', '["Ako vjetar okrene, hoće. Spremimo dokumente za svaki slučaj.", "Za tri tjedna. Do tada vozite s privremenom potvrdom.", "Petnaestog svibnja, idemo u Krapinu."]'::jsonb, 0, null, 'Hoće li evakuirati kamp?', null, null, 'Діалог «Пожежа поблизу»: «Hoće li evakuirati kamp?» (Чи евакуюють кемпінг?) — «Ako vjetar okrene, hoće. Spremimo dokumente za svaki slučaj.» (Якщо вітер зміниться, евакуюють. Приготуймо документи про всяк випадок.).', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('eb74d612-c8c0-5432-b288-44a4915382f6', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dašo, gdje bacamo ostatke hrane?', '["Oko sto eura, ali materijal nije uključen.", "U smeđu kantu za biootpad. Ali ne u plastičnoj vrećici!", "Možemo, ako raspodijelimo zadatke. Ja ću preuzeti izvještaj."]'::jsonb, 1, null, 'Dašo, gdje bacamo ostatke hrane?', null, null, 'Діалог «Біовідходи»: «Dašo, gdje bacamo ostatke hrane?» (Дашо, куди викидаємо залишки їжі?) — «U smeđu kantu za biootpad. Ali ne u plastičnoj vrećici!» (У коричневий бак для біовідходів. Але не в пластиковому пакеті!).', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1548f549-79e4-5903-b58f-023b245549a7', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Jesi li blokirao kartice?', '["Jesam, odmah. Srećom, novac je bio u drugom džepu.", "Trideset posto. Boravišna pristojba se plaća na dolasku.", "Prvo odabereš djelatnost i upišeš obrt u obrtni registar."]'::jsonb, 0, null, 'Jesi li blokirao kartice?', null, null, 'Діалог «Картки»: «Jesi li blokirao kartice?» (Ти заблокував картки?) — «Jesam, odmah. Srećom, novac je bio u drugom džepu.» (Так, одразу. На щастя, гроші були в іншій кишені.).', (select id from public.lessons where id = '6c0efc81-fd32-55c6-8e57-b1885e387093'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('89d28d90-f9a1-5ea5-a697-bed8075e9fd5', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Susjedo, kamo ide ova plastična boca?', '["У зелений контейнер на майданчику для сортування, на розі вулиці.", "Найкраще повернути її в магазин, отримаєте заставу назад.", "У жовтий мішок. Синій контейнер — для паперу й картону."]'::jsonb, 1, null, null, 'Darja: Susjedo, kamo ide ova plastična boca?
Susjeda: Najbolje je vratiti je u trgovinu, dobijete povratnu naknadu.
Darja: A ostala plastika i limenke?
Susjeda: U žutu vreću. Plavi spremnik je za papir i karton.
Darja: A staklo?
Susjeda: U zeleni spremnik na zelenom otoku, na uglu ulice.', 'Darja: Сусідко, куди йде ця пластикова пляшка?
Susjeda: Найкраще повернути її в магазин, отримаєте заставу назад.
Darja: А решта пластику й бляшанки?
Susjeda: У жовтий мішок. Синій контейнер — для паперу й картону.
Darja: А скло?
Susjeda: У зелений контейнер на майданчику для сортування, на розі вулиці.', 'Діалог «Що куди?»: «Susjedo, kamo ide ova plastična boca?» — «Najbolje je vratiti je u trgovinu, dobijete povratnu naknadu.», тобто «Найкраще повернути її в магазин, отримаєте заставу назад.».', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c3531ccc-9ca6-5cde-886b-add29eabddb6', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Možete li ga opisati?', '["Я подивлюся. У трамваях щодня ми знаходимо багато гаманців.", "Він коричневий, шкіряний, з документами й картками.", "Добрий день, учора я загубив гаманець. Думаю, що залишив його в трамваї."]'::jsonb, 1, null, null, 'Ivan: Dobar dan, jučer sam izgubio novčanik. Mislim da sam ga ostavio u tramvaju.
Službenica: Možete li ga opisati?
Ivan: Smeđ je, kožni, s dokumentima i karticama.
Službenica: Pogledat ću. U tramvajima svaki dan pronađemo puno novčanika.
Ivan: Jeste li ga pronašli?
Službenica: Još nije stigao. Ispunite obrazac, javit ćemo Vam se ako se nađe.', 'Ivan: Добрий день, учора я загубив гаманець. Думаю, що залишив його в трамваї.
Službenica: Можете його описати?
Ivan: Він коричневий, шкіряний, з документами й картками.
Službenica: Я подивлюся. У трамваях щодня ми знаходимо багато гаманців.
Ivan: Ви його знайшли?
Službenica: Ще не надійшов. Заповніть бланк, ми повідомимо вас, якщо знайдеться.', 'Діалог «У бюро знахідок»: «Možete li ga opisati?» — «Smeđ je, kožni, s dokumentima i karticama.», тобто «Він коричневий, шкіряний, з документами й картками.».', (select id from public.lessons where id = '6c0efc81-fd32-55c6-8e57-b1885e387093'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('96a6e875-f3de-5139-9a40-99e0a1e59429', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Для Спліта червоне попередження». Що ви скажете?', null, '["Za Split je crveno upozorenje.", "U hitnom slučaju nazovite 112.", "U subotu je akcija čišćenja plaže."]'::jsonb, 0, null, null, null, null, '«Для Спліта червоне попередження.» — «Za Split je crveno upozorenje.».', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3536403e-6289-5834-97c2-8c94b032922d', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «крижаний дощ»', null, '[]'::jsonb, null, 'ledena kiša', null, null, null, '«крижаний дощ» — ledena kiša.', (select id from public.lessons where id = '88f2e9d5-51e4-5ff4-b18b-b221ac12117d'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7c19ef44-a584-52fd-9574-6658bd7ed325', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Треба берегти довкілля.»', null, '["Moramo", "okoliš.", "čuvati"]'::jsonb, null, 'Moramo čuvati okoliš.', null, null, null, '«Треба берегти довкілля.» — «Moramo čuvati okoliš.».', (select id from public.lessons where id = '03c6044d-1ebf-5dee-becb-e4748f65511c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('fdd65d5c-b61a-5645-87b9-f060e24488f1', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Ми сортуємо папір, пластик і скло.»', null, '[]'::jsonb, null, 'Odvajamo papir, plastiku i staklo.', null, null, null, '«Ми сортуємо папір, пластик і скло.» — «Odvajamo papir, plastiku i staklo.».', (select id from public.lessons where id = '8d6a1367-0183-5c35-b6df-ddfbe23a4152'), 'PUBLISHED', 'claude_assessment_a2_v2');
  insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
  values ('assessment', v_aid, null, 'PUBLISHED', 'auto_passed', 'script', '[]'::jsonb, 'Бета: перевірка рівня A2 (програма A2 v2, схема 2026-11-07) — завдання з діалогів і вправ уроків A2. Потрібна перевірка носієм.');
