-- Перевірка модуля A2.10 · Модуль A2.10 — Медіа, культура й думки · 12 завдань
do $$
declare v_aid uuid := '5062045d-2da0-5448-87fa-36798547cb5a';
begin
  if exists (select 1 from public.assessment_items where id = '55e09487-87f4-56b8-984a-8af4fed38289') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m10' and id <> v_aid) then
    raise exception 'Тест a2-m10 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m10', 'module', 'Перевірка модуля A2.10', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          '285d2a27-68a4-5302-afc3-9595d071647a', 10, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('55e09487-87f4-56b8-984a-8af4fed38289', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Ти був у тому новому ресторані в центрі?", "Спокусливо. До коли діє?", "Гаразд. У вас є аудіокниги хорватською?"]'::jsonb, 2, null, 'U redu. Imate li zvučne knjige na hrvatskom?', null, null, 'Прозвучало: «U redu. Imate li zvučne knjige na hrvatskom?» — «Гаразд. У вас є аудіокниги хорватською?».', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5ce05a03-c5f4-5379-9282-2f77400a7b00', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Яка головна проблема?", "Треба написати «лише серйозні покупці»?", "Дар’є, що ти читаєш?"]'::jsonb, 0, null, 'Koji je glavni problem?', null, null, 'Прозвучало: «Koji je glavni problem?» — «Яка головна проблема?».', (select id from public.lessons where id = 'd6b9db92-a933-5d45-8f17-f6e911a97ab1'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('884c9315-0549-5178-933f-c577ea7447c8', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Чому люди переїжджають у місто?', 'Grad ili selo?', '["Там легше знайти роботу", "Там дешевше", "Там чистіше повітря"]'::jsonb, 0, null, null, 'Mnogi ljudi u Hrvatskoj sele se iz malih mjesta u veće gradove, osobito u Zagreb. U gradu je lakše naći posao, a ima i više škola, bolnica i kafića. Ali život u gradu je skuplji: stanovi su skupi, a promet je gust. Na selu je mirnije i zrak je čišći. Kuće su jeftinije, a ljudi se bolje poznaju. S druge strane, autobus ponekad vozi samo dva puta dnevno, a do najbliže bolnice treba voziti pola sata. Što je bolje? Mislim da to ovisi o tome što vam je u životu važnije.', 'Багато людей у Хорватії переїжджають із маленьких населених пунктів у більші міста, особливо в Загреб. У місті легше знайти роботу, а ще там більше шкіл, лікарень і кафе. Але життя в місті дорожче: квартири дорогі, а рух щільний. На селі спокійніше й повітря чистіше. Будинки дешевші, а люди краще знають одне одного. З іншого боку, автобус іноді їздить лише двічі на день, а до найближчої лікарні треба їхати пів години. Що краще? Я думаю, це залежить від того, що для вас важливіше в житті.', 'Текст «Місто чи село?». Правильна відповідь: «Там легше знайти роботу».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ef1a8b23-35d4-5b77-ad79-7117b6d22383', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li rad od kuće dobar ili loš?', '["Ovisi o poslu. Za mene ima smisla, naime živim daleko.", "Tražila sam i našla sam! Dobila sam ponudu u Splitu.", "Ako vjetar okrene, hoće. Spremimo dokumente za svaki slučaj."]'::jsonb, 0, null, 'Je li rad od kuće dobar ili loš?', null, null, 'Діалог «Робота з дому»: «Je li rad od kuće dobar ili loš?» (Робота з дому — це добре чи погано?) — «Ovisi o poslu. Za mene ima smisla, naime živim daleko.» (Залежить від роботи. Для мене це має сенс, річ у тім, що я живу далеко.).', (select id from public.lessons where id = 'd6b9db92-a933-5d45-8f17-f6e911a97ab1'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('40d119d0-76eb-5215-b398-6aac2c4fc169', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što slušaš u autu?', '["Podcast o hrvatskoj povijesti. Nova epizoda izlazi petkom.", "Sjećam se, bila je stroga, ali pravedna.", "Daša. Napravit ću s njom primopredaju i uključiti automatski odgovor."]'::jsonb, 0, null, 'Što slušaš u autu?', null, null, 'Діалог «Улюблений подкаст»: «Što slušaš u autu?» (Що ти слухаєш в авто?) — «Podcast o hrvatskoj povijesti. Nova epizoda izlazi petkom.» (Подкаст про історію Хорватії. Новий епізод виходить по п’ятницях.).', (select id from public.lessons where id = '92bd4e0c-f9df-5edb-a65e-9549fe1ef1b8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('dbdc4143-4512-5238-8664-eaff5430b7a1', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'U redu. Imate li zvučne knjige na hrvatskom?', '["Medicinska sestra je regulirana profesija, pa treba stručno priznavanje.", "Imamo, i e-knjige. Posudba traje tri tjedna.", "Jesmo. Jako smo se posramili, nikad to neću zaboraviti."]'::jsonb, 1, null, 'U redu. Imate li zvučne knjige na hrvatskom?', null, null, 'Діалог «У бібліотеці»: «U redu. Imate li zvučne knjige na hrvatskom?» (Гаразд. У вас є аудіокниги хорватською?) — «Imamo, i e-knjige. Posudba traje tri tjedna.» (Є, і електронні книги. Позика — на три тижні.).', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('825ce0aa-06af-5f18-af15-9dbeb7250e8b', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što vrijedi posjetiti?', '["Дашо, порадь мені якесь місце на вихідні.", "Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!", "Щиро раджу Самобор. Це прихована перлина біля Загреба."]'::jsonb, 1, null, null, 'Darja: Daša, preporuči mi neko mjesto za vikend.
Daša: Toplo preporučujem Samobor. To je skriveni dragulj blizu Zagreba.
Darja: Što vrijedi posjetiti?
Daša: Stari grad i šetnicu uz potok. I svakako probaj kremšnitu!
Darja: Je li tamo velika gužva?
Daša: Vikendom da. Isplati se otići rano ujutro.', 'Darja: Дашо, порадь мені якесь місце на вихідні.
Daša: Щиро раджу Самобор. Це прихована перлина біля Загреба.
Darja: Що варто відвідати?
Daša: Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!
Darja: Там великий натовп?
Daša: На вихідних так. Варто поїхати рано вранці.', 'Діалог «Куди піти у вихідні?»: «Što vrijedi posjetiti?» — «Stari grad i šetnicu uz potok. I svakako probaj kremšnitu!», тобто «Старе місто й стежку вздовж потічка. І обов’язково скуштуй кремшниту!».', (select id from public.lessons where id = '57ba42b9-17e0-5dda-9de1-f0354b45f845'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3f19650f-9423-5c77-981d-4d41e7737d73', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Je li bolji od prošlog?', '["Набагато цікавіший за попередній. Головна героїня — молода поліцейська.", "Детектив однієї хорватської письменниці. Дія відбувається у Спліті.", "Трохи, але розумію дедалі більше. Він захопливий, не можу відірватися."]'::jsonb, 0, null, null, 'Daša: Darja, što čitaš?
Darja: Kriminalistički roman jedne hrvatske spisateljice. Radnja se događa u Splitu.
Daša: Je li težak za čitanje na hrvatskom?
Darja: Malo, ali sve više razumijem. Napet je, ne mogu ga ispustiti iz ruku.
Daša: Je li bolji od prošlog?
Darja: Puno je zanimljiviji od prošlog. Glavni lik je mlada policajka.', 'Daša: Дар’є, що ти читаєш?
Darja: Детектив однієї хорватської письменниці. Дія відбувається у Спліті.
Daša: Важко читати хорватською?
Darja: Трохи, але розумію дедалі більше. Він захопливий, не можу відірватися.
Daša: Він кращий за попередній?
Darja: Набагато цікавіший за попередній. Головна героїня — молода поліцейська.', 'Діалог «Що ти читаєш?»: «Je li bolji od prošlog?» — «Puno je zanimljiviji od prošlog. Glavni lik je mlada policajka.», тобто «Набагато цікавіший за попередній. Головна героїня — молода поліцейська.».', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('fe21f743-2d32-5d5a-898b-fc4760f6c4ad', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Яке твій улюблений жанр?». Що ви скажете?', null, '["Preporuči mi neki restoran.", "Koji je tvoj omiljeni žanr?", "Toplo preporučujem ovu knjigu."]'::jsonb, 1, null, null, null, null, '«Яке твій улюблений жанр?» — «Koji je tvoj omiljeni žanr?».', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('13ffc415-ae01-541f-89c1-a0bea5217902', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «розділ»', null, '[]'::jsonb, null, 'poglavlje', null, null, null, '«розділ» — poglavlje.', (select id from public.lessons where id = '2e7e2800-1867-5d3e-9cee-d712b2e8e9e0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8ba40715-f4ce-5abc-a342-0bb53f6aa1e1', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Не розповідай мені кінця!»', null, '["mi", "Nemoj", "kraj!", "otkriti"]'::jsonb, null, 'Nemoj mi otkriti kraj!', null, null, null, '«Не розповідай мені кінця!» — «Nemoj mi otkriti kraj!».', (select id from public.lessons where id = 'ef11286d-512d-524a-9edc-e760010d1037'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('42dc7e24-9c69-52f3-bf58-7270b5dbeade', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Шукаю квартиру, яка має балкон.»', null, '[]'::jsonb, null, 'Tražim stan koji ima balkon.', null, null, null, '«Шукаю квартиру, яка має балкон.» — «Tražim stan koji ima balkon.».', (select id from public.lessons where id = '3fc81316-dca8-5661-88c1-eaf2b61aec07'), 'PUBLISHED', 'claude_assessment_a2_v2');
