begin
  if exists (select 1 from public.assessment_items where id = '49dbb0e3-6dbc-5c87-b038-02db860f0ad1') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m11' and id <> v_aid) then
    raise exception 'Тест a2-m11 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m11', 'module', 'Перевірка модуля A2.11', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          '81b58843-3837-5c58-ab5d-4d16e30620b2', 11, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('49dbb0e3-6dbc-5c87-b038-02db860f0ad1', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Нам треба роззуватися?", "Є лижні схили?", "Коли тут збір винограду?"]'::jsonb, 0, null, 'Trebamo li se izuti?', null, null, 'Прозвучало: «Trebamo li se izuti?» — «Нам треба роззуватися?».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c489509d-09e8-56a6-82a5-cf6f9f4ab3ac', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["І Сіньська алка, старовинний лицарський турнір. Щосерпня.", "Кава — це не напій, а спілкування. Не поспішай!", "Годину. Пагорби, виноградники, а бабусі говорять кайкавською."]'::jsonb, 2, null, 'Sat vremena. Brežuljci, vinogradi, a bake govore kajkavski.', null, null, 'Прозвучало: «Sat vremena. Brežuljci, vinogradi, a bake govore kajkavski.» — «Годину. Пагорби, виноградники, а бабусі говорять кайкавською.».', (select id from public.lessons where id = 'a312ce34-22d7-56e3-a38e-106205ee21c0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('49bb9762-1bbe-540e-8e92-b79afe0878d6', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Іноді. Але індичку з млинцями всі розуміють!", "Важливо зберігати такі звичаї.", "Фіш-паприкаш — як наша юшка, тільки гостріший!"]'::jsonb, 1, null, 'Važno je očuvati takve običaje.', null, null, 'Прозвучало: «Važno je očuvati takve običaje.» — «Важливо зберігати такі звичаї.».', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('536e6364-0452-57d5-96ee-b875fc00be59', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Zvuči odlično. Što preporučujete za piće?', '["Našu malvaziju ili teran. Vino je iz našeg vinograda.", "Ovisi o prihodu. Napravimo zajedno poslovni plan.", "Malo povučen, ali iskren i marljiv."]'::jsonb, 0, null, 'Zvuči odlično. Što preporučujete za piće?', null, null, 'Діалог «В агротуризмі»: «Zvuči odlično. Što preporučujete za piće?» (Звучить чудово. Що порадите з напоїв?) — «Našu malvaziju ili teran. Vino je iz našeg vinograda.» (Нашу мальвазію або теран. Вино з нашого винограднику.).', (select id from public.lessons where id = 'df44c302-d9be-51e9-9c3f-a5faf4ca04a6'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('edc4aff7-d2c6-514e-8c50-09218b3799da', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebamo li se izuti?', '["Ovisi o poslu. Za mene ima smisla, naime živim daleko.", "Navikla se. Najvažnija je zdrava prehrana i redoviti pregledi.", "Da, mama će vam dati papuče. I pohvalite mamin kolač!"]'::jsonb, 2, null, 'Trebamo li se izuti?', null, null, 'Діалог «У гості»: «Trebamo li se izuti?» (Нам треба роззуватися?) — «Da, mama će vam dati papuče. I pohvalite mamin kolač!» (Так, мама дасть вам капці. І похваліть мамин пиріг!).', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f4d5fc42-cc3a-513d-a233-8b95e7d58bf4', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što je klapa?', '["Puno je zanimljiviji od prošlog. Glavni lik je mlada policajka.", "Liječnik kaže da neće. Srećom!", "Dalmatinsko pjevanje, a cappella, obično osam glasova."]'::jsonb, 2, null, 'Što je klapa?', null, null, 'Діалог «Клапа на набережній»: «Što je klapa?» (Що таке клапа?) — «Dalmatinsko pjevanje, a cappella, obično osam glasova.» (Далматинський спів а капела, зазвичай вісім голосів.).', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('369f047e-d79d-52e9-ab44-2c87134ada8c', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'A ako sam sita? Mogu li odbiti?', '["Заведено приносити вино або квіти. І не запізнюйтеся.", "Так, мама дасть вам капці. І похваліть мамин пиріг!", "Складно. Візьми хоча б маленький шматочок, це чемно."]'::jsonb, 2, null, null, 'Darja: Ivana, idemo prvi put kod tvojih roditelja. Što da donesem?
Ivana: Običaj je donijeti vino ili cvijeće. I ne kasnite.
Darja: Trebamo li se izuti?
Ivana: Da, mama će vam dati papuče. I pohvalite mamin kolač!
Darja: A ako sam sita? Mogu li odbiti?
Ivana: Teško. Uzmi barem mali komad, to je pristojno.', 'Darja: Івано, ми вперше йдемо до твоїх батьків. Що мені принести?
Ivana: Заведено приносити вино або квіти. І не запізнюйтеся.
Darja: Нам треба роззуватися?
Ivana: Так, мама дасть вам капці. І похваліть мамин пиріг!
Darja: А якщо я сита? Можна відмовитися?
Ivana: Складно. Візьми хоча б маленький шматочок, це чемно.', 'Діалог «У гості»: «A ako sam sita? Mogu li odbiti?» — «Teško. Uzmi barem mali komad, to je pristojno.», тобто «Складно. Візьми хоча б маленький шматочок, це чемно.».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e4bfe4e4-52c4-5b09-8ccc-5beb374ce551', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Znaš li da Hrvatska ima puno nematerijalne baštine?', '["У нас вишивка, українська вишиванка.", "Я знаю про пазьке мереживо. Його передають з покоління в покоління.", "Дар’є, сьогодні ввечері виступ клапи на набережній. Приходь!"]'::jsonb, 1, null, null, 'Ivan: Znaš li da Hrvatska ima puno nematerijalne baštine?
Darja: Znam za pašku čipku. Prenosi se s koljena na koljeno.
Ivan: I sinjska alka, stari viteški turnir. Svakog kolovoza.
Darja: Kod nas je vez, ukrajinska vezena košulja.
Ivan: Važno je očuvati takve običaje.', 'Ivan: Ти знаєш, що Хорватія має багато нематеріальної спадщини?
Darja: Я знаю про пазьке мереживо. Його передають з покоління в покоління.
Ivan: І Сіньська алка, старовинний лицарський турнір. Щосерпня.
Darja: У нас вишивка, українська вишиванка.
Ivan: Важливо зберігати такі звичаї.', 'Діалог «Спадщина»: «Znaš li da Hrvatska ima puno nematerijalne baštine?» — «Znam za pašku čipku. Prenosi se s koljena na koljeno.», тобто «Я знаю про пазьке мереживо. Його передають з покоління в покоління.».', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3e57e8fd-2ead-5c71-a022-8a9d0d97abd6', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Поля соняшнику нагадують мені Україну». Що ви скажете?', null, '["Trebamo li se izuti?", "Večeras je nastup klape.", "Polja suncokreta podsjećaju me na Ukrajinu."]'::jsonb, 2, null, null, null, null, '«Поля соняшнику нагадують мені Україну.» — «Polja suncokreta podsjećaju me na Ukrajinu.».', (select id from public.lessons where id = '4bd3a563-65f6-596c-8f20-aabce6c7811f'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5ab0b6df-536c-5c30-89a8-ebede8429df2', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «дичина»', null, '[]'::jsonb, null, 'divljač', null, null, null, '«дичина» — divljač.', (select id from public.lessons where id = 'ab060253-8099-5e7d-bfaa-1b1a7655c229'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0026b933-a456-5b5e-93ad-df4dc134fde7', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «До старших звертаються на «ви».»', null, '["se", "Starijima", "persira."]'::jsonb, null, 'Starijima se persira.', null, null, null, '«До старших звертаються на «ви».» — «Starijima se persira.».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c276d4b3-eee4-5035-a5d8-7099949c5c64', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Що мені принести?»', null, '[]'::jsonb, null, 'Što da donesem?', null, null, null, '«Що мені принести?» — «Što da donesem?».', (select id from public.lessons where id = '7d3c3501-a381-5b3c-a0a2-b269f3dff137'), 'PUBLISHED', 'claude_assessment_a2_v2');
