  ('1272bc78-4d41-5908-b450-7e09c40f709c', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Землетрус не включено, хіба що з додатковим внеском.", "Ритм життя. Тут він повільніший, люди розслабленіші.", "Дар’є, твій український паспорт скоро закінчується."]'::jsonb, 2, null, 'Darja, tvoja ukrajinska putovnica uskoro ističe.', null, null, 'Прозвучало: «Darja, tvoja ukrajinska putovnica uskoro ističe.» — «Дар’є, твій український паспорт скоро закінчується.».', (select id from public.lessons where id = '5e298915-e179-5d58-bca0-6531c7b43a46'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('42e7d5e4-9f23-5f89-ad5f-7e9caa936b86', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Що ви відзначаєте двадцять четвертого серпня?", "Дар’є, ти чула про українську асоціацію в Рієці?", "Одяг, кава й шоколад. Чи можна надіслати ліки?"]'::jsonb, 1, null, 'Darja, jesi li čula za ukrajinsku udrugu u Rijeci?', null, null, 'Прозвучало: «Darja, jesi li čula za ukrajinsku udrugu u Rijeci?» — «Дар’є, ти чула про українську асоціацію в Рієці?».', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('62135386-51e1-5c34-b1f5-e8fa799ad0ec', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Лікар каже, що ні. На щастя!", "Дуже. Мені бракує друзів і нашого хліба.", "Я принесу й щось для дітей."]'::jsonb, 2, null, 'Donijet ću i nešto za djecu.', null, null, 'Прозвучало: «Donijet ću i nešto za djecu.» — «Я принесу й щось для дітей.».', (select id from public.lessons where id = '55fdd530-ac46-5ba9-a5de-9fd5944b0c8c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1bf4b9be-0d86-56d4-bc03-0b9b89076dab', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Koliko traje dostava?', '["Pet do sedam dana. Mami pošaljite broj za praćenje.", "Na jednom portalu. Bilo je na naslovnici.", "Jesmo. Ali nakon što smo našli stan, osjetila sam olakšanje."]'::jsonb, 0, null, 'Koliko traje dostava?', null, null, 'Діалог «Посилка мамі»: «Koliko traje dostava?» (Скільки триває доставка?) — «Pet do sedam dana. Mami pošaljite broj za praćenje.» (Від п’яти до семи днів. Надішліть мамі номер для відстеження.).', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9bbd587f-221f-502b-9fab-f1ce3c440dd1', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?', '["Ritam života. Ovdje je sporiji, ljudi su opušteniji.", "Obje. A roditelji su oboje u Osijeku.", "Daša. Napravit ću s njom primopredaju i uključiti automatski odgovor."]'::jsonb, 0, null, 'Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?', null, null, 'Діалог «Що інакше?»: «Darja, što je najviše drukčije u Hrvatskoj nego u Ukrajini?» (Дар’є, що найбільше відрізняється в Хорватії від України?) — «Ritam života. Ovdje je sporiji, ljudi su opušteniji.» (Ритм життя. Тут він повільніший, люди розслабленіші.).', (select id from public.lessons where id = '0465a2cd-1da9-5a6e-a47d-434fc8bee342'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('942e26bd-f14c-5703-8372-c140609610a7', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu. Gdje je sabirno mjesto?', '["Našu malvaziju ili teran. Vino je iz našeg vinograda.", "U dvorani škole. Trebamo dugotrajnu hranu i higijenske potrepštine.", "Hoće. Na kraju piše „ovjereno“, s pečatom i potpisom."]'::jsonb, 1, null, 'Mogu. Gdje je sabirno mjesto?', null, null, 'Діалог «Пункт збору»: «Mogu. Gdje je sabirno mjesto?» (Можу. Де пункт збору?) — «U dvorani škole. Trebamo dugotrajnu hranu i higijenske potrepštine.» (У шкільній залі. Нам потрібна їжа тривалого зберігання й засоби гігієни.).', (select id from public.lessons where id = '55fdd530-ac46-5ba9-a5de-9fd5944b0c8c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9289994f-8440-58d0-8304-5621550cca2e', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Darja, na kojem jeziku govoriš djeci?', '["Доньці легше. Вона говорить хорватською без акценту і вчить кирилицю.", "Удома українською, надворі хорватською. Це наше правило.", "Іноді. Син потроху забуває українську, тому я читаю йому щовечора."]'::jsonb, 1, null, null, 'Ivana: Darja, na kojem jeziku govoriš djeci?
Darja: Kod kuće ukrajinski, vani hrvatski. To je naše pravilo.
Ivana: Miješaju li jezike?
Darja: Ponekad. Sin polako zaboravlja ukrajinski, zato mu čitam svake večeri.
Ivana: A kći?
Darja: Kćeri je lakše. Govori hrvatski bez naglaska i uči ćirilicu.', 'Ivana: Дар’є, якою мовою ти говориш з дітьми?
Darja: Удома українською, надворі хорватською. Це наше правило.
Ivana: Вони змішують мови?
Darja: Іноді. Син потроху забуває українську, тому я читаю йому щовечора.
Ivana: А донька?
Darja: Доньці легше. Вона говорить хорватською без акценту і вчить кирилицю.', 'Діалог «Дві мови»: «Darja, na kojem jeziku govoriš djeci?» — «Kod kuće ukrajinski, vani hrvatski. To je naše pravilo.», тобто «Удома українською, надворі хорватською. Це наше правило.».', (select id from public.lessons where id = '56d06c34-2631-5ca9-a3a3-b0df910556dc'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('96021271-6e30-5fbd-96ce-b6dfd69d3515', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što obilježavate dvadeset četvrtog kolovoza?', '["Можна й мені прийти?", "Звісно! Зустріч відкрита для всіх.", "День Незалежності України. Культурне товариство організовує концерт."]'::jsonb, 2, null, null, 'Ivan: Što obilježavate dvadeset četvrtog kolovoza?
Darja: Dan neovisnosti Ukrajine. Kulturno društvo organizira koncert.
Ivan: Mogu li i ja doći?
Darja: Naravno! Druženje je otvoreno svima.', 'Ivan: Що ви відзначаєте двадцять четвертого серпня?
Darja: День Незалежності України. Культурне товариство організовує концерт.
Ivan: Можна й мені прийти?
Darja: Звісно! Зустріч відкрита для всіх.', 'Діалог «День Незалежності»: «Što obilježavate dvadeset četvrtog kolovoza?» — «Dan neovisnosti Ukrajine. Kulturno društvo organizira koncert.», тобто «День Незалежності України. Культурне товариство організовує концерт.».', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('742444f8-4a3b-5652-870a-ff24ec3aeebe', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Ми допомагаємо людям з документами». Що ви скажете?', null, '["Pomažemo ljudima oko dokumenata.", "Kod kuće govorimo ukrajinski.", "Koliko traje dostava?"]'::jsonb, 0, null, null, null, null, '«Ми допомагаємо людям з документами.» — «Pomažemo ljudima oko dokumenata.».', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('45163e99-2b9b-565c-9a53-ce3dfa98ec76', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «відзначити»', null, '[]'::jsonb, null, 'obilježiti', null, null, null, '«відзначити» — obilježiti.', (select id from public.lessons where id = '695e119d-c66c-5c02-9f3e-a2a161403585'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f71c6cdd-58bb-5af3-8e2c-1c41becc451d', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Мама отримала гроші вчора.»', null, '["je", "novac", "primila", "Mama", "jučer."]'::jsonb, null, 'Mama je primila novac jučer.', null, null, null, '«Мама отримала гроші вчора.» — «Mama je primila novac jučer.».', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f95dbe6f-d8cf-5543-9cf6-54dfe26f0da2', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Я хотіла б надіслати посилку в Україну.»', null, '[]'::jsonb, null, 'Htjela bih poslati paket u Ukrajinu.', null, null, null, '«Я хотіла б надіслати посилку в Україну.» — «Htjela bih poslati paket u Ukrajinu.».', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_a2_v2');
