  values (v_aid, 'a2-m13', 'module', 'Перевірка модуля A2.13', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          '47c98d89-5811-5425-af88-26e8249d361b', 13, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('8dcdd376-e6d6-5f46-a9e6-af2a922686b4', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Я б відкрила власну справу, маленьку галерею. Малювала б море.", "Ритм життя. Тут він повільніший, люди розслабленіші.", "Найважливіше — гарний настрій. Наступного разу — просто неба!"]'::jsonb, 0, null, 'Otvorila bih vlastiti posao, malu galeriju. Slikala bih more.', null, null, 'Прозвучало: «Otvorila bih vlastiti posao, malu galeriju. Slikala bih more.» — «Я б відкрила власну справу, маленьку галерею. Малювала б море.».', (select id from public.lessons where id = '00cd6ab0-29c4-5eab-94a4-5319d76fbce4'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1e2a217f-2279-5362-8f9e-0887fcf69642', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Без проблем. Можемо перенести зустріч?", "Перепрошую, мені можна зайти без шапочки?", "Хто принесе їжу?"]'::jsonb, 2, null, 'Tko će donijeti hranu?', null, null, 'Прозвучало: «Tko će donijeti hranu?» — «Хто принесе їжу?».', (select id from public.lessons where id = '7595b9eb-8f9a-5772-8bae-259a79428d33'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3da4bdb6-4470-5253-8528-4b7845bf12de', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Де Марко спатиме перші дві ночі?', 'Planovi za ljeto', '["В апартаментах", "У готелі", "У наметі"]'::jsonb, 2, null, null, 'Marko: Što ćete raditi ovo ljeto?
Oksana: U srpnju ćemo ostati u Zagrebu jer radim. U kolovozu ćemo otići na more na tjedan dana.
Marko: Kamo idete?
Oksana: Na Krk. Već smo rezervirali mali apartman blizu plaže. Djeca će se kupati cijeli dan!
Marko: Super! Mi ćemo ići u planine, u Gorski kotar. Tamo je ljeti svježe i nema gužve.
Oksana: To zvuči lijepo. Hoćete li spavati u šatoru?
Marko: Hoćemo, prve dvije noći. Poslije ćemo spavati u maloj kući kod prijatelja.', 'Марко: Що ви робитимете цього літа?
Оксана: У липні ми залишимося в Загребі, бо я працюю. У серпні поїдемо на море на тиждень.
Марко: Куди їдете?
Оксана: На Крк. Ми вже забронювали маленькі апартаменти біля пляжу. Діти купатимуться цілий день!
Марко: Чудово! А ми поїдемо в гори, у Горскі-Котар. Там улітку свіжо й немає натовпу.
Оксана: Звучить гарно. Ви спатимете в наметі?
Марко: Так, перші дві ночі. Потім спатимемо в маленькому будиночку в друзів.', 'Текст «Плани на літо». Правильна відповідь: «У наметі».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d3ee38e5-aafd-5aa3-9513-3b841b2da2d3', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što vam je dugoročni plan?', '["Mi bismo htjeli neko mirno mjesto, bez velike gužve.", "Kupiti stan. Štedimo svaki mjesec po malo.", "Preko NIAS-a, trebate vjerodajnicu, na primjer iz banke."]'::jsonb, 1, null, 'Što vam je dugoročni plan?', null, null, 'Діалог «Довгий план»: «Što vam je dugoročni plan?» (Який у вас довгостроковий план?) — «Kupiti stan. Štedimo svaki mjesec po malo.» (Купити квартиру. Відкладаємо щомісяця потроху.).', (select id from public.lessons where id = 'f2760130-fd69-5932-978c-cc424aaefafa'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('daf617c3-ab65-5041-9a10-32ce6bbdd411', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Nema problema. Može idući ponedjeljak u devet?', '["Može. Javit ću Vam ako se nešto promijeni.", "Gore napiši svoje podatke, a ispod naslovljeno na Gradski ured.", "Našu malvaziju ili teran. Vino je iz našeg vinograda."]'::jsonb, 0, null, 'Nema problema. Može idući ponedjeljak u devet?', null, null, 'Діалог «Скасування в лікаря»: «Nema problema. Može idući ponedjeljak u devet?» (Без проблем. Можна наступного понеділка о дев’ятій?) — «Može. Javit ću Vam ako se nešto promijeni.» (Можна. Я вам повідомлю, якщо щось зміниться.).', (select id from public.lessons where id = '0b054356-d4b4-5f6e-b7e9-3dc8f3c9d4ff'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b9afb7d7-3a9b-5436-b85c-33cd0fb8ae53', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Bilo je super! Tko će raspremiti?', '["Raspremit ćemo zajedno, brzo će ići.", "Ritam života. Ovdje je sporiji, ljudi su opušteniji.", "U ponedjeljak. Pismeni ispit, pa usmeni."]'::jsonb, 0, null, 'Bilo je super! Tko će raspremiti?', null, null, 'Діалог «Після вечірки»: «Bilo je super! Tko će raspremiti?» (Було супер! Хто прибиратиме?) — «Raspremit ćemo zajedno, brzo će ići.» (Приберемо разом, швидко впораємося.).', (select id from public.lessons where id = '7595b9eb-8f9a-5772-8bae-259a79428d33'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d1f17971-a4fc-551f-8e09-fee5786aed1a', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ivane, možeš li mi u subotu pričuvati psa?', '["Супер. Натомість я допоможу тобі з переїздом.", "Можу, хіба що мене не викличуть на роботу.", "Це чесно. Щойно знатиму розклад, повідомлю тобі."]'::jsonb, 1, null, null, 'Daša: Ivane, možeš li mi u subotu pričuvati psa?
Ivan: Mogu, osim ako me ne pozovu na posao.
Daša: Super. Zauzvrat ću ti pomoći s preseljenjem.
Ivan: To je pošteno. Čim budem znao raspored, javit ću ti.', 'Daša: Іване, можеш у суботу наглянути за моїм псом?
Ivan: Можу, хіба що мене не викличуть на роботу.
Daša: Супер. Натомість я допоможу тобі з переїздом.
Ivan: Це чесно. Щойно знатиму розклад, повідомлю тобі.', 'Діалог «Допомога за допомогу»: «Ivane, možeš li mi u subotu pričuvati psa?» — «Mogu, osim ako me ne pozovu na posao.», тобто «Можу, хіба що мене не викличуть на роботу.».', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('2ccb7deb-b7c6-597d-acf5-1995e08e891d', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'U redu. Želite li novi termin?', '["Добрий день, мушу скасувати запис на завтра. Я хворий.", "Можна. Я вам повідомлю, якщо щось зміниться.", "Так. Перепрошую за скасування в останню хвилину."]'::jsonb, 2, null, null, 'Ivan: Dobar dan, moram otkazati termin za sutra. Bolestan sam.
Sestra: U redu. Želite li novi termin?
Ivan: Želim. Ispričavam se zbog otkazivanja u zadnji čas.
Sestra: Nema problema. Može idući ponedjeljak u devet?
Ivan: Može. Javit ću Vam ako se nešto promijeni.', 'Ivan: Добрий день, мушу скасувати запис на завтра. Я хворий.
Sestra: Гаразд. Бажаєте новий час?
Ivan: Так. Перепрошую за скасування в останню хвилину.
Sestra: Без проблем. Можна наступного понеділка о дев’ятій?
Ivan: Можна. Я вам повідомлю, якщо щось зміниться.', 'Діалог «Скасування в лікаря»: «U redu. Želite li novi termin?» — «Želim. Ispričavam se zbog otkazivanja u zadnji čas.», тобто «Так. Перепрошую за скасування в останню хвилину.».', (select id from public.lessons where id = '0b054356-d4b4-5f6e-b7e9-3dc8f3c9d4ff'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8ed115c7-5ed7-5a72-8ca8-89aa3e24ea18', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «У разі, якщо я запізнюся, починайте без мене». Що ви скажете?', null, '["U slučaju da kasnim, počnite bez mene.", "Odgovara li ti u četvrtak?", "Oprosti, iskrsnulo mi je nešto."]'::jsonb, 0, null, null, null, null, '«У разі, якщо я запізнюся, починайте без мене.» — «U slučaju da kasnim, počnite bez mene.».', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f31fedd1-290d-502a-82ec-c4b0099816f4', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «домовилися»', null, '[]'::jsonb, null, 'dogovoreno', null, null, null, '«домовилися» — dogovoreno.', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a1141969-356f-583a-9aca-76929a0e8787', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я прийду, за умови, що не буде дощу.»', null, '["Doći", "ću,", "kiša.", "pod", "uvjetom", "pada", "ne", "da"]'::jsonb, null, 'Doći ću, pod uvjetom da ne pada kiša.', null, null, null, '«Я прийду, за умови, що не буде дощу.» — «Doći ću, pod uvjetom da ne pada kiša.».', (select id from public.lessons where id = 'f5189d33-5f78-51d5-a1ec-5712c5c87a88'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b7caf396-32ec-5b95-b035-509e898f4935', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Витрати поділимо.»', null, '[]'::jsonb, null, 'Troškove ćemo podijeliti.', null, null, null, '«Витрати поділимо.» — «Troškove ćemo podijeliti.».', (select id from public.lessons where id = '7595b9eb-8f9a-5772-8bae-259a79428d33'), 'PUBLISHED', 'claude_assessment_a2_v2');
