-- Перевірка модуля A2.14 · Модуль A2.14 — Підсумок A2: моє життя в Хорватії · 12 завдань
do $$
declare v_aid uuid := 'b15d250d-ae46-58f2-a90d-9c7f68e44e81';
begin
  if exists (select 1 from public.assessment_items where id = '2ac36bb4-1fc2-5f84-ac34-d945d08469cf') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-m14' and id <> v_aid) then
    raise exception 'Тест a2-m14 уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-m14', 'module', 'Перевірка модуля A2.14', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          'a22f1345-0879-5cde-ad47-4a76556dcf7e', 14, 0.70, 0.50, 6, 'Після модуля: 12 завдань на 4 навички — розумію, спілкуюся, переказую, кажу. ~6 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('2ac36bb4-1fc2-5f84-ac34-d945d08469cf', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Бачиш, мова дала тобі впевненість.", "«Дорога Олено». Потім напиши новини, коротко.", "І P. S. — передавай вітання мамі!"]'::jsonb, 2, null, 'I P. S. — pozdravi mamu!', null, null, 'Прозвучало: «I P. S. — pozdravi mamu!» — «І P. S. — передавай вітання мамі!».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('889bb262-2ffb-5e45-89c6-d714bcf9c176', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Як було в лікаря?", "Що ви плануєте надалі?", "А через п’ять років?"]'::jsonb, 1, null, 'Što namjeravate ubuduće?', null, null, 'Прозвучало: «Što namjeravate ubuduće?» — «Що ви плануєте надалі?».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ae896d82-e136-575d-89df-222e1477f926', v_aid, 3, 'A2', 'reading', 'understand', 'multiple_choice', 'Скільки коштує вхід?', 'Festival u Zagrebu', '["5 євро", "10 євро", "Безкоштовно"]'::jsonb, 2, null, null, 'Ovog vikenda u Zagrebu se održava Festival hrane i vina. Na Trgu bana Jelačića bit će više od pedeset štandova s domaćim proizvodima iz cijele Hrvatske. Posjetitelji će moći probati sireve, pršut, med i vina iz Istre, Slavonije i Dalmacije. Za djecu su organizirane radionice i predstave. Festival je otvoren od petka do nedjelje, od 10 do 22 sata, a ulaz je besplatan. Organizatori očekuju više od dvadeset tisuća posjetitelja. Ako bude padala kiša, program će se preseliti na tržnicu Dolac.', 'Цими вихідними в Загребі проходить Фестиваль їжі та вина. На площі бана Єлачича буде понад п’ятдесят наметів із домашніми продуктами з усієї Хорватії. Відвідувачі зможуть скуштувати сири, пршут, мед і вина з Істрії, Славонії та Далмації. Для дітей підготували майстер-класи й вистави. Фестиваль відкритий із п’ятниці до неділі, з 10 до 22 години, вхід безкоштовний. Організатори очікують понад двадцять тисяч відвідувачів. Якщо йтиме дощ, програму перенесуть на ринок Долац.', 'Текст «Фестиваль у Загребі». Правильна відповідь: «Безкоштовно».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0cf4d3be-6066-5f10-9c50-476639504d5f', v_aid, 4, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako je bilo kod liječnika?', '["Jako. Nedostaju mi prijatelji i naš kruh.", "Dan neovisnosti Ukrajine. Kulturno društvo organizira koncert.", "Bila sam sama, bez prevoditelja! Znala sam opisati simptome."]'::jsonb, 2, null, 'Kako je bilo kod liječnika?', null, null, 'Діалог «Без перекладача»: «Kako je bilo kod liječnika?» (Як було в лікаря?) — «Bila sam sama, bez prevoditelja! Znala sam opisati simptome.» (Я була сама, без перекладача! Змогла описати симптоми.).', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('85a5d702-f273-51ea-be66-cfd39c1a537f', v_aid, 5, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kad pogledaš unatrag, što ti je najveće postignuće?', '["Djeca. Prilagodila su se i govore dva jezika.", "Jesmo. Jako smo se posramili, nikad to neću zaboraviti.", "Pišu, učiteljica im provjeri zadaću. Ručak je u školskoj kuhinji."]'::jsonb, 0, null, 'Kad pogledaš unatrag, što ti je najveće postignuće?', null, null, 'Діалог «Підсумок»: «Kad pogledaš unatrag, što ti je najveće postignuće?» (Коли озираєшся назад, що твоє найбільше досягнення?) — «Djeca. Prilagodila su se i govore dva jezika.» (Діти. Вони адаптувалися й говорять двома мовами.).', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('6a68cea7-88a4-5234-990c-f683495b66c8', v_aid, 6, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako da zamolim nešto?', '["Petnaestog svibnja, idemo u Krapinu.", "„Molila bih Vas…“ ili „Bila bih Vam zahvalna…“", "Teški. Nisam se znala snaći, a nedostajala mi je mama."]'::jsonb, 1, null, 'Kako da zamolim nešto?', null, null, 'Діалог «Офіційний лист»: «Kako da zamolim nešto?» (Як мені про щось попросити?) — «„Molila bih Vas…“ ili „Bila bih Vam zahvalna…“» («Я б просила вас…» або «Я була б вам вдячна…»).', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1a1156fe-4f34-5a92-b5a2-b8fd26e82cc5', v_aid, 7, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Što namjeravate ubuduće?', '["Я виросла в маленькому містечку, а молодість провела в Харкові. Там навчалася й працювала.", "Я складу іспит B1 і хотіла б працювати вчителькою.", "Дар’є, розкажіть нам свою історію життя."]'::jsonb, 1, null, null, 'Novinarka: Darja, ispričajte nam svoju životnu priču.
Darja: Odrasla sam u malom gradu, a mladost sam provela u Harkivu. Tamo sam studirala i radila.
Novinarka: A onda ste došli u Hrvatsku.
Darja: Da, 2022. Prve mjesece sam učila jezik, a onda sam našla posao u vrtiću.
Novinarka: Što namjeravate ubuduće?
Darja: Položit ću ispit B1 i htjela bih raditi kao učiteljica.', 'Novinarka: Дар’є, розкажіть нам свою історію життя.
Darja: Я виросла в маленькому містечку, а молодість провела в Харкові. Там навчалася й працювала.
Novinarka: А потім ви приїхали до Хорватії.
Darja: Так, у 2022-му. Перші місяці я вчила мову, а потім знайшла роботу в садочку.
Novinarka: Що ви плануєте надалі?
Darja: Я складу іспит B1 і хотіла б працювати вчителькою.', 'Діалог «Інтерв’ю для журналу»: «Što namjeravate ubuduće?» — «Položit ću ispit B1 i htjela bih raditi kao učiteljica.», тобто «Я складу іспит B1 і хотіла б працювати вчителькою.».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a72c3a8e-a8f9-53ee-83a7-74f9d73933fb', v_aid, 8, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Rodni list imam samo na ukrajinskom. Što točno trebate?', '["До мене. Мені потрібне свідоцтво про народження й ваша посвідка.", "Засвідчений переклад. Можете принести мені його завтра.", "Саме так. Це останній крок."]'::jsonb, 1, null, null, 'Darja: Dobar dan, trebam potvrdu za vrtić. Kome se mogu obratiti?
Službenica: Meni. Trebam rodni list i Vašu iskaznicu.
Darja: Rodni list imam samo na ukrajinskom. Što točno trebate?
Službenica: Ovjereni prijevod. Možete mi ga donijeti sutra.
Darja: Jesam li dobro razumjela: sutra prijevod, i onda je riješeno?
Službenica: Točno. To je zadnji korak.', 'Darja: Добрий день, мені потрібна довідка для садочка. До кого я можу звернутися?
Službenica: До мене. Мені потрібне свідоцтво про народження й ваша посвідка.
Darja: Свідоцтво в мене лише українською. Що саме вам потрібно?
Službenica: Засвідчений переклад. Можете принести мені його завтра.
Darja: Чи правильно я зрозуміла: завтра переклад, і тоді все вирішено?
Službenica: Саме так. Це останній крок.', 'Діалог «В установі»: «Rodni list imam samo na ukrajinskom. Što točno trebate?» — «Ovjereni prijevod. Možete mi ga donijeti sutra.», тобто «Засвідчений переклад. Можете принести мені його завтра.».', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('2ed8ae8a-459b-5daa-892a-1601c27900ca', v_aid, 9, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Я була б вам вдячна за відповідь». Що ви скажете?', null, '["Jesam li dobro razumjela?", "Bila bih Vam zahvalna na odgovoru.", "Jedva čekam da se vidimo."]'::jsonb, 1, null, null, null, null, '«Я була б вам вдячна за відповідь.» — «Bila bih Vam zahvalna na odgovoru.».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8229f809-b49c-57b6-a7c4-ec06b032a103', v_aid, 10, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «впевненість у собі»', null, '[]'::jsonb, null, 'samopouzdanje', null, null, null, '«впевненість у собі» — samopouzdanje.', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a4a54875-c928-56ed-b4fe-90b7c28b4d72', v_aid, 11, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я дуже сумую за тобою.»', null, '["mi", "nedostaješ.", "Jako"]'::jsonb, null, 'Jako mi nedostaješ.', null, null, null, '«Я дуже сумую за тобою.» — «Jako mi nedostaješ.».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('68ba3b83-e452-56f3-ac1b-0c33e51d61a2', v_aid, 12, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Через п’ять років я бачу себе у власній квартирі.»', null, '[]'::jsonb, null, 'Za pet godina vidim se u vlastitom stanu.', null, null, null, '«Через п’ять років я бачу себе у власній квартирі.» — «Za pet godina vidim se u vlastitom stanu.».', (select id from public.lessons where id = '9b5d0ec7-4573-5f83-8cec-acc6997335de'), 'PUBLISHED', 'claude_assessment_a2_v2');
