-- Перевірка середини рівня A2 · 30 завдань
do $$
declare v_aid uuid := '7717f2c4-9f82-579b-bb82-7e21cd4184b8';
begin
  if exists (select 1 from public.assessment_items where id = '34e393fb-7350-55f7-9aae-b658ff0c55d4') then return; end if;  -- уже створено
  if exists (select 1 from public.assessments where slug = 'a2-mid' and id <> v_aid) then
    raise exception 'Тест a2-mid уже є з іншим id — звірте базу';
  end if;
  insert into public.assessments (id, slug, kind, title_ua, version, status, source, cefr, module_id, order_index, pass_ratio,
                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-mid', 'mid', 'Перевірка середини рівня A2', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          null, 50, 0.70, 0.50, 15, 'Середина рівня (модулі A2.1–A2.7): 30 завдань на 4 навички. ~15 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('34e393fb-7350-55f7-9aae-b658ff0c55d4', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Це медуза. Вийдіть з моря, будь ласка.", "Ой! Щось мене обпекло за ногу!", "Не ходить через негоду. Море дуже хвилясте."]'::jsonb, 1, null, 'Joj! Nešto me opeklo na nozi!', null, null, 'Прозвучало: «Joj! Nešto me opeklo na nozi!» — «Ой! Щось мене обпекло за ногу!».', (select id from public.lessons where id = 'bd9353b6-9d9e-5192-8124-f6a2dcf3f178'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d4bc524c-b706-595f-acb6-be4df2445237', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А як надіслати йому пропозицію?", "Ти маєш право на вихідну допомогу?", "Добре. Чи окупилося б це першого року?"]'::jsonb, 0, null, 'A kako da mu pošaljem ponudu?', null, null, 'Прозвучало: «A kako da mu pošaljem ponudu?» — «А як надіслати йому пропозицію?».', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0df836d2-152a-5c89-ad6f-f300a6ce69ee', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добрий день, я мама Філіпа. Як у нього справи?", "До коли ти маєш його надіслати?", "Дар’є, Філіп ходитиме на якийсь гурток?"]'::jsonb, 0, null, 'Dobar dan, ja sam Filipova mama. Kako mu ide?', null, null, 'Прозвучало: «Dobar dan, ja sam Filipova mama. Kako mu ide?» — «Добрий день, я мама Філіпа. Як у нього справи?».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f49b110a-e739-5f7f-bd4e-ee495ff1202d', v_aid, 4, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре, бо попередній був хвалькуватий і егоїстичний.", "Добре, я тобі пробачаю. Я теж на тебе кричала.", "Я хочу поговорити з керівником магазину."]'::jsonb, 2, null, 'Želim razgovarati s voditeljem trgovine.', null, null, 'Прозвучало: «Želim razgovarati s voditeljem trgovine.» — «Я хочу поговорити з керівником магазину.».', (select id from public.lessons where id = '2760a712-4fa2-56fd-b036-8427682ad804'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9317053a-c58b-5b1f-aaa4-cb3fea249925', v_aid, 5, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре. Марку, тобі доручаю презентацію.", "Гаразд. Надішли мені довідку, коли отримаєш.", "Іду сьогодні. Мені відкриють лікарняний."]'::jsonb, 2, null, 'Idem danas. Otvorit će mi bolovanje.', null, null, 'Прозвучало: «Idem danas. Otvorit će mi bolovanje.» — «Іду сьогодні. Мені відкриють лікарняний.».', (select id from public.lessons where id = '0e0d07a2-2a6c-5090-ab84-3089f20a48b8'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('499252e7-5a99-56f4-8c03-63d511af51de', v_aid, 6, 'A2', 'reading', 'understand', 'multiple_choice', 'Скільки годин вони ходили?', 'Kako je bilo za vikend?', '["Дві", "П’ять", "Десять"]'::jsonb, 1, null, null, 'Ivana: Bok, Taras! Kako je bilo za vikend?
Taras: Super! U subotu smo bili na Plitvicama. Hodali smo pet sati.
Ivana: Prekrasno! Jeste li vidjeli velike slapove?
Taras: Jesmo. Bilo je puno ljudi, ali vrijedilo je. A ti?
Ivana: Ja sam bila kod kuće. Bila sam bolesna, pa sam samo spavala i gledala filmove.
Taras: Joj, žao mi je! Je li ti sada bolje?
Ivana: Bolje mi je, hvala. Sljedeći put idem s vama!
Taras: Dogovoreno!', 'Івана: Привіт, Тарасе! Як минули вихідні?
Тарас: Чудово! У суботу ми були на Плітвицьких озерах. Ходили п’ять годин.
Івана: Чудово! Ви бачили великі водоспади?
Тарас: Бачили. Було багато людей, але воно того було варте. А ти?
Івана: Я була вдома. Я хворіла, тож тільки спала й дивилася фільми.
Тарас: Ой, шкода! Тобі вже краще?
Івана: Краще, дякую. Наступного разу піду з вами!
Тарас: Домовилися!', 'Текст «Як минули вихідні?». Правильна відповідь: «П’ять».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c7c02598-2e93-57a3-b058-f70b2924c830', v_aid, 7, 'A2', 'reading', 'understand', 'multiple_choice', 'О котрій Данило мусить вставати?', 'Prvi tjedan na novom poslu', '["О сьомій", "О п’ятій", "О шостій"]'::jsonb, 1, null, null, 'Danilo je prošli tjedan počeo raditi u velikom skladištu blizu Zagreba. Prvi dan mu je voditelj pokazao cijelo skladište i objasnio pravila. Radno vrijeme je od šest do dva, pa Danilo mora ustati u pet. Prva dva dana bila su teška: nije razumio sve što su kolege govorili, a bilo ga je sram pitati. Treći dan jedan kolega, Marko, ponudio mu je pomoć. Sada mu Marko polako objašnjava riječi koje ne zna. Danilo je zadovoljan: plaća je dobra, a kolege su ljubazni. Sljedeći mjesec dobit će ugovor na godinu dana.', 'Минулого тижня Данило почав працювати на великому складі біля Загреба. Першого дня керівник показав йому весь склад і пояснив правила. Робочий час — із шостої до другої, тому Данило мусить вставати о п’ятій. Перші два дні були важкими: він не розумів усього, що говорили колеги, а питати соромився. Третього дня один колега, Марко, запропонував йому допомогу. Тепер Марко повільно пояснює йому слова, яких він не знає. Данило задоволений: зарплата хороша, а колеги привітні. Наступного місяця він отримає договір на рік.', 'Текст «Перший тиждень на новій роботі». Правильна відповідь: «О п’ятій».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d17cc479-49b8-5f1e-8b1b-fd4888a7794e', v_aid, 8, 'A2', 'reading', 'understand', 'multiple_choice', 'Чому Тарас хоче відпустку?', 'Molba za godišnji odmor', '["Приїжджає родина з України", "Він хворий", "Він переїжджає"]'::jsonb, 0, null, null, 'Poštovana gospođo Babić,
htio bih uzeti godišnji odmor od 4. do 15. kolovoza. U to vrijeme moja obitelj dolazi iz Ukrajine i želio bih provesti nekoliko dana s njima. Razgovarao sam s kolegom Jurićem i on me može zamijeniti na smjenama. Sve zadatke završit ću do kraja srpnja. Ako taj termin nije moguć, molim vas da mi predložite drugi.
Hvala na razumijevanju.
S poštovanjem,
Taras Kovalenko', 'Шановна пані Бабич!
Я хотів би взяти відпустку з 4 по 15 серпня. У цей час до мене приїжджає родина з України, і я хотів би провести з ними кілька днів. Я поговорив із колегою Юричем, і він може замінити мене на змінах. Усі завдання я закінчу до кінця липня. Якщо ці дати неможливі, прошу запропонувати мені інші.
Дякую за розуміння.
З повагою,
Тарас Коваленко', 'Текст «Прохання про відпустку». Правильна відповідь: «Приїжджає родина з України».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f80b88d5-44c2-5df7-beb5-7e5aa6b4680d', v_aid, 9, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'To nam odgovara. Imamo bebu. Biste li mogli staviti dječji krevetić?', '["Obje. A roditelji su oboje u Osijeku.", "Naravno, bez nadoplate. Za rezervaciju trebate uplatiti predujam.", "Sjećam se, bila je stroga, ali pravedna."]'::jsonb, 1, null, 'To nam odgovara. Imamo bebu. Biste li mogli staviti dječji krevetić?', null, null, 'Діалог «Дзвінок господині»: «To nam odgovara. Imamo bebu. Biste li mogli staviti dječji krevetić?» (Нам це підходить. У нас немовля. Чи не могли б ви поставити дитяче ліжечко?) — «Naravno, bez nadoplate. Za rezervaciju trebate uplatiti predujam.» (Звісно, без доплати. Для бронювання вам треба внести передоплату.).', (select id from public.lessons where id = '2aaf70f9-5a0c-53a3-a621-e42cc4548661'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8a0d9a8c-770d-58ad-9372-093d769280a8', v_aid, 10, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebam li staviti šefa u kopiju?', '["Za obljetnicu braka roditelja, svake godine u lipnju.", "Da, i zamoli klijenta da potvrdi primitak.", "Navikla se. Najvažnija je zdrava prehrana i redoviti pregledi."]'::jsonb, 1, null, 'Trebam li staviti šefa u kopiju?', null, null, 'Діалог «Лист клієнтові»: «Trebam li staviti šefa u kopiju?» (Мені треба поставити шефа в копію?) — «Da, i zamoli klijenta da potvrdi primitak.» (Так, і попроси клієнта підтвердити отримання.).', (select id from public.lessons where id = '531f3eac-8358-513b-ab35-d57fe69eb64b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('16ccf4b8-18d4-5d61-98f7-6e5f23cf6227', v_aid, 11, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hoće li biti posljedica?', '["Deset posto. Preuzeo sam i nove zadatke.", "Liječnik kaže da neće. Srećom!", "Možemo, ako raspodijelimo zadatke. Ja ću preuzeti izvještaj."]'::jsonb, 1, null, 'Hoće li biti posljedica?', null, null, 'Діалог «Зламана рука»: «Hoće li biti posljedica?» (Чи будуть наслідки?) — «Liječnik kaže da neće. Srećom!» (Лікар каже, що ні. На щастя!).', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('63b2b0f8-0e50-5036-a58c-52d8d34fc13a', v_aid, 12, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kakav je novi kolega?', '["Vrlo nestašan. Stalno sam se penjao po drveću.", "Stalno sam pod stresom na poslu. Ne mogu se usredotočiti.", "Malo povučen, ali iskren i marljiv."]'::jsonb, 2, null, 'Kakav je novi kolega?', null, null, 'Діалог «Новий колега»: «Kakav je novi kolega?» (Який новий колега?) — «Malo povučen, ali iskren i marljiv.» (Трохи замкнутий, але щирий і працьовитий.).', (select id from public.lessons where id = '7b43692b-44ae-5e4f-9022-4290ce7b5eaa'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('86969d87-be24-53bd-a02e-1f12d9d16b24', v_aid, 13, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Dobar dan, gdje se predaje zahtjev za vrtić?', '["Ovdje, u pisarnici. Ovo je Vaš urudžbeni broj.", "Daša. Napravit ću s njom primopredaju i uključiti automatski odgovor.", "Dobro! Predavačica kaže da brzo napredujem."]'::jsonb, 0, null, 'Dobar dan, gdje se predaje zahtjev za vrtić?', null, null, 'Діалог «У канцелярії»: «Dobar dan, gdje se predaje zahtjev za vrtić?» (Добрий день, де подають заяву до садочка?) — «Ovdje, u pisarnici. Ovo je Vaš urudžbeni broj.» (Тут, у канцелярії. Ось ваш вхідний номер.).', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('4de5c7f4-af48-5f67-9e24-a12e38d6ea34', v_aid, 14, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Hvala. Ako ne riješite problem, biste li nas premjestili u drugu sobu?', '["Hoće. Na kraju piše „ovjereno“, s pečatom i potpisom.", "Naravno. Ispričavamo se zbog neugodnosti.", "Zahtjev moram dopuniti u roku od osam dana."]'::jsonb, 1, null, 'Hvala. Ako ne riješite problem, biste li nas premjestili u drugu sobu?', null, null, 'Діалог «Не працює кондиціонер»: «Hvala. Ako ne riješite problem, biste li nas premjestili u drugu sobu?» (Дякую. Якщо не розв’яжете проблему, чи не могли б ви переселити нас в інший номер?) — «Naravno. Ispričavamo se zbog neugodnosti.» (Звісно. Просимо вибачення за незручності.).', (select id from public.lessons where id = '778e1a8f-01d6-5bc0-b3e3-3e3123551c8b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ea4eef07-ce58-549c-b57e-3fbcceaa31dd', v_aid, 15, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Što ti pomaže za opuštanje?', '["Preko NIAS-a, trebate vjerodajnicu, na primjer iz banke.", "Boravak u prirodi. Vikendom idem na Sljeme i isključim mobitel.", "Prodavač je bio neljubazan. To je neprihvatljivo."]'::jsonb, 1, null, 'Što ti pomaže za opuštanje?', null, null, 'Діалог «Як відпочити?»: «Što ti pomaže za opuštanje?» (Що допомагає тобі розслабитися?) — «Boravak u prirodi. Vikendom idem na Sljeme i isključim mobitel.» (Перебування на природі. На вихідних я їду на Слєме й вимикаю мобільний.).', (select id from public.lessons where id = '4b8782ab-0559-531b-a393-38aaf599a97c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e349ea48-5ac4-5c87-982f-0d72a0ea098d', v_aid, 16, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Dobra večer. Što je bilo?', '["Ой, перепрошую, я не знав, що чути. Зроблю тихіше.", "Музика дуже гучна, а діти мають спати.", "Дякую, що пішли нам назустріч."]'::jsonb, 1, null, null, 'Darja: Dobra večer, susjede. Oprostite što smetam.
Susjed: Dobra večer. Što je bilo?
Darja: Glazba je jako glasna, a djeca moraju spavati.
Susjed: Oh, oprostite, nisam znao da se čuje. Utišat ću.
Darja: Hvala što ste nam izašli u susret.', 'Darja: Добрий вечір, сусіде. Перепрошую, що турбую.
Susjed: Добрий вечір. Що сталося?
Darja: Музика дуже гучна, а діти мають спати.
Susjed: Ой, перепрошую, я не знав, що чути. Зроблю тихіше.
Darja: Дякую, що пішли нам назустріч.', 'Діалог «Шум увечері»: «Dobra večer. Što je bilo?» — «Glazba je jako glasna, a djeca moraju spavati.», тобто «Музика дуже гучна, а діти мають спати.».', (select id from public.lessons where id = '5252662a-abfc-517a-9bde-8683121a53c5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f5c0ec70-8965-5c8d-b843-559aaddcdaa4', v_aid, 17, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Kako ti ide na tečaju?', '["І мені. Тому щодня пишу домашнє завдання й вправляюся.", "А граматика? Мені відмінки були найважчі.", "Добре! Викладачка каже, що я швидко роблю успіхи."]'::jsonb, 2, null, null, 'Daša: Kako ti ide na tečaju?
Darja: Dobro! Predavačica kaže da brzo napredujem.
Daša: A gramatika? Meni su padeži bili najteži.
Darja: I meni. Zato svaki dan pišem domaću zadaću i vježbam.
Daša: Bravo. Kad budeš spremna, upiši se na ispit iz hrvatskog.', 'Daša: Як тобі на курсі?
Darja: Добре! Викладачка каже, що я швидко роблю успіхи.
Daša: А граматика? Мені відмінки були найважчі.
Darja: І мені. Тому щодня пишу домашнє завдання й вправляюся.
Daša: Молодець. Коли будеш готова, запишися на іспит з хорватської.', 'Діалог «Після заняття»: «Kako ti ide na tečaju?» — «Dobro! Predavačica kaže da brzo napredujem.», тобто «Добре! Викладачка каже, що я швидко роблю успіхи.».', (select id from public.lessons where id = '8190831a-549a-544a-962b-4f716a895a32'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5f54b28d-a827-5765-95c0-049127d9ef12', v_aid, 18, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jeste li dobili kaznu?', '["Ми пішли в кіно, але директор спіймав нас на вулиці.", "Одного разу ми всім класом прогуляли урок історії.", "Так. Нам було дуже соромно, я ніколи цього не забуду."]'::jsonb, 2, null, null, 'Marko: Jednom smo cijeli razred markirali sat povijesti.
Ivan: I što se dogodilo?
Marko: Otišli smo u kino, ali ravnatelj nas je uhvatio na ulici.
Ivan: Jeste li dobili kaznu?
Marko: Jesmo. Jako smo se posramili, nikad to neću zaboraviti.', 'Marko: Одного разу ми всім класом прогуляли урок історії.
Ivan: І що сталося?
Marko: Ми пішли в кіно, але директор спіймав нас на вулиці.
Ivan: Вас покарали?
Marko: Так. Нам було дуже соромно, я ніколи цього не забуду.', 'Діалог «Прогул»: «Jeste li dobili kaznu?» — «Jesmo. Jako smo se posramili, nikad to neću zaboraviti.», тобто «Так. Нам було дуже соромно, я ніколи цього не забуду.».', (select id from public.lessons where id = '92226a59-39e3-5dba-b0df-1e91b3dd2210'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ffd8fdeb-9949-5de9-b23a-ae233b1bbcee', v_aid, 19, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Nije, ona je u Ukrajini. Treba li i ona doći?', '["Не треба. Ви підписуєте особисто, а я засвідчую підпис.", "Добрий день, мені потрібна довіреність на сестру. Вона ходитиме в банк замість мене.", "Паспорт і дані сестри. Довіреність можна написати й англійською."]'::jsonb, 0, null, null, 'Darja: Dobar dan, trebam punomoć za sestru. Ona će umjesto mene ići u banku.
Bilježnica: Je li sestra ovdje?
Darja: Nije, ona je u Ukrajini. Treba li i ona doći?
Bilježnica: Ne treba. Vi potpisujete osobno, a ja ovjeravam potpis.
Darja: Što trebam donijeti?
Bilježnica: Putovnicu i sestrine podatke. Punomoć se može napisati i na engleskom.', 'Darja: Добрий день, мені потрібна довіреність на сестру. Вона ходитиме в банк замість мене.
Bilježnica: Сестра тут?
Darja: Ні, вона в Україні. Їй теж треба прийти?
Bilježnica: Не треба. Ви підписуєте особисто, а я засвідчую підпис.
Darja: Що мені треба принести?
Bilježnica: Паспорт і дані сестри. Довіреність можна написати й англійською.', 'Діалог «Довіреність»: «Nije, ona je u Ukrajini. Treba li i ona doći?» — «Ne treba. Vi potpisujete osobno, a ja ovjeravam potpis.», тобто «Не треба. Ви підписуєте особисто, а я засвідчую підпис.».', (select id from public.lessons where id = '856c691f-4467-561f-a344-377ca275dbba'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('17850bf5-c0ef-5355-b0cf-6d496c59737f', v_aid, 20, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Як у нього справи в школі?». Що ви скажете?', null, '["Kako mu ide u školi?", "Mogu li dobiti vaučer za obrazovanje?", "Zanima me večernji tečaj."]'::jsonb, 0, null, null, null, null, '«Як у нього справи в школі?» — «Kako mu ide u školi?».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('01e63d21-1583-5420-ba2a-10748421e499', v_aid, 21, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Коли буде готове пальто?». Що ви скажете?', null, '["Samo me malo podšišajte, molim.", "Začepio se odvod u kuhinji.", "Kada će kaput biti gotov?"]'::jsonb, 2, null, null, null, null, '«Коли буде готове пальто?» — «Kada će kaput biti gotov?».', (select id from public.lessons where id = '8ab1c1e5-b217-5175-ab89-325106da3504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d8cec046-c14a-508c-9f91-a3756b22728e', v_aid, 22, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Чи є вільний столик біля моря?». Що ви скажете?', null, '["Htio bih ulaznicu za jedanaest.", "Uzmi cipelice za more zbog ježinaca.", "Imate li slobodan stol uz more?"]'::jsonb, 2, null, null, null, null, '«Чи є вільний столик біля моря?» — «Imate li slobodan stol uz more?».', (select id from public.lessons where id = '098e590d-283c-56db-927d-80488d4bce45'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8dc3b7f6-66c0-50ec-bbf2-ef81a2a6dfbd', v_aid, 23, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «набрякнути»', null, '[]'::jsonb, null, 'nateći', null, null, null, '«набрякнути» — nateći.', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('84bdbba0-fa46-5c12-921b-7818b9169fa9', v_aid, 24, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «обґрунтування»', null, '[]'::jsonb, null, 'obrazloženje', null, null, null, '«обґрунтування» — obrazloženje.', (select id from public.lessons where id = '0b5f1880-b274-51c1-9d55-32a9873040a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('8d8fe160-9374-591b-b0b8-e1a4579de59b', v_aid, 25, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «посваритися»', null, '[]'::jsonb, null, 'posvađati se', null, null, null, '«посваритися» — posvađati se.', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c030bc32-db2c-56f6-ae54-1283e240e540', v_aid, 26, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Конкурс оголошують у травні.»', null, '["objavljuje", "svibnju.", "Natječaj", "u", "se"]'::jsonb, null, 'Natječaj se objavljuje u svibnju.', null, null, null, '«Конкурс оголошують у травні.» — «Natječaj se objavljuje u svibnju.».', (select id from public.lessons where id = 'aad2c656-7750-545f-88be-b36c1cdb3b79'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('09ca43b4-97f6-51bf-9b7c-e2deae738151', v_aid, 27, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Я не хотіла тебе образити.»', null, '["htjela", "te", "uvrijediti.", "Nisam"]'::jsonb, null, 'Nisam te htjela uvrijediti.', null, null, null, '«Я не хотіла тебе образити.» — «Nisam te htjela uvrijediti.».', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e2b44503-dc65-55b6-8b85-08e330c8d7ae', v_aid, 28, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Ми швидко звикли до нового міста.»', null, '["grad.", "se", "Brzo", "smo", "na", "priviknuli", "novi"]'::jsonb, null, 'Brzo smo se priviknuli na novi grad.', null, null, null, '«Ми швидко звикли до нового міста.» — «Brzo smo se priviknuli na novi grad.».', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('49954fe9-edc2-5722-b53e-72dd55a089e1', v_aid, 29, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «У мене паморочиться голова.»', null, '[]'::jsonb, null, 'Vrti mi se.', null, null, null, '«У мене паморочиться голова.» — «Vrti mi se.».', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d9cc5957-b3c5-52c9-a5a3-7c5768253a37', v_aid, 30, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Мушу розповісти тобі, що сталося.»', null, '[]'::jsonb, null, 'Moram ti ispričati što se dogodilo.', null, null, null, '«Мушу розповісти тобі, що сталося.» — «Moram ti ispričati što se dogodilo.».', (select id from public.lessons where id = '6440a67e-bb4f-507e-ae20-ebf59c66424e'), 'PUBLISHED', 'claude_assessment_a2_v2');
