                                  area_min_ratio, estimated_minutes, description_ua)
  values (v_aid, 'a2-final', 'final', 'Фінальна перевірка рівня A2', 1, 'PUBLISHED', 'claude_assessment_a2_v2', 'A2',
          null, 100, 0.70, 0.50, 25, 'Кінець рівня (усі 14 модулів A2): 48 завдань на 4 навички. ~25 хв.')
  on conflict (id) do nothing;
  insert into public.assessment_items (id, assessment_id, order_index, cefr, skill, area, item_type, prompt_ua, prompt_hr, options,
    correct_index, answer_text, audio_hr, passage_hr, passage_ua, explanation_ua, lesson_id, status, source) values
  ('d80be5ac-8f3e-5bf4-8c2e-82a00f95ba7b', v_aid, 1, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Супер. А на пам’ять?", "А що їй з’їсти?", "Охоче! Стежка важка?"]'::jsonb, 1, null, 'A što da jede?', null, null, 'Прозвучало: «A što da jede?» — «А що їй з’їсти?».', (select id from public.lessons where id = 'a312ce34-22d7-56e3-a38e-106205ee21c0'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9e93b110-3aa7-516e-866e-9553221dfd3f', v_aid, 2, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["«Дорога Олено». Потім напиши новини, коротко.", "Бачиш, мова дала тобі впевненість.", "«В очікуванні вашої відповіді, з повагою»."]'::jsonb, 1, null, 'Vidiš, jezik ti je dao samopouzdanje.', null, null, 'Прозвучало: «Vidiš, jezik ti je dao samopouzdanje.» — «Бачиш, мова дала тобі впевненість.».', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1503620d-ad7c-5cca-b885-6e2bceb1a958', v_aid, 3, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре. Шкода лише матеріальна?", "Чудово. Де я можу його забрати?", "Що сталося?"]'::jsonb, 0, null, 'Dobro. Je li šteta samo materijalna?', null, null, 'Прозвучало: «Dobro. Je li šteta samo materijalna?» — «Добре. Шкода лише матеріальна?».', (select id from public.lessons where id = '306ddbde-6662-5d7e-8c58-eb2c2a17a504'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('6e84217b-b820-54c8-bc66-0ac707b13a2b', v_aid, 4, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А наприкінці?", "Молодець! А на роботі?", "А офіційний лист? Що інакше?"]'::jsonb, 0, null, 'A na kraju?', null, null, 'Прозвучало: «A na kraju?» — «А наприкінці?».', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('1e87e7bf-3e39-5274-afa3-a2a6efa41688', v_aid, 5, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["У садочку кишкова інфекція. У нього є температура?", "Іване, тебе довго не було. Ти хворів?", "Дар’є, у твоєї бабусі цукровий діабет?"]'::jsonb, 1, null, 'Ivane, dugo te nije bilo. Jesi li bio bolestan?', null, null, 'Прозвучало: «Ivane, dugo te nije bilo. Jesi li bio bolestan?» — «Іване, тебе довго не було. Ти хворів?».', (select id from public.lessons where id = '266c7f3d-8fb2-5fce-8127-3b52f464ecbe'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7838a639-3e91-5380-8454-06ea0e6f35d3', v_aid, 6, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["А оцінки? У нас було до дванадцяти.", "Пані, у Філіпа два невиправдані пропуски.", "Супер. Зі студентським дешево їсиш у їдальні."]'::jsonb, 1, null, 'Gospođo, Filip ima dva neopravdana izostanka.', null, null, 'Прозвучало: «Gospođo, Filip ima dva neopravdana izostanka.» — «Пані, у Філіпа два невиправдані пропуски.».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('777d40dc-407f-5210-8c17-e2bb42d5fe1a', v_aid, 7, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Добре, мені це підходить. Дякую.", "Добре. Я повідомлю вас, коли закрию лікарняний.", "Спитай у службі зайнятості про грант на самозайнятість."]'::jsonb, 2, null, 'Pitaj Zavod za potporu za samozapošljavanje.', null, null, 'Прозвучало: «Pitaj Zavod za potporu za samozapošljavanje.» — «Спитай у службі зайнятості про грант на самозайнятість.».', (select id from public.lessons where id = 'd9c5c952-3ae5-521d-9ccb-c22ccaeb8aab'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('333abd4c-26bb-515d-b31f-bf8e82b0e562', v_aid, 8, 'A2', 'listening', 'understand', 'multiple_choice', 'Послухайте. Що сказали?', null, '["Одяг, кава й шоколад. Чи можна надіслати ліки?", "А що ти любиш тут?", "Дар’є, чому ви волонтерите в соціальній їдальні?"]'::jsonb, 2, null, 'Darja, zašto volontirate u pučkoj kuhinji?', null, null, 'Прозвучало: «Darja, zašto volontirate u pučkoj kuhinji?» — «Дар’є, чому ви волонтерите в соціальній їдальні?».', (select id from public.lessons where id = '55fdd530-ac46-5ba9-a5de-9fd5944b0c8c'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9adb9a00-297b-567d-a299-754a83920d70', v_aid, 9, 'A2', 'reading', 'understand', 'multiple_choice', 'Коли Олені стало краще?', 'Olena se prehladila', '["У понеділок", "У суботу", "У середу"]'::jsonb, 1, null, null, 'Prošli tjedan Olena se jako prehladila. Imala je temperaturu, boljelo ju je grlo i stalno je kašljala. Prva dva dana pila je čaj s medom i ležala u krevetu, ali nije joj bilo bolje. U srijedu je nazvala svoju liječnicu i naručila se na pregled. Liječnica ju je pregledala i rekla da ima upalu grla. Dala joj je recept za antibiotik i bolovanje do petka. Olena je kupila lijek u ljekarni i uzimala ga je dva puta dnevno. U subotu se već osjećala puno bolje. Sljedeći put odmah će nazvati liječnicu.', 'Минулого тижня Олена сильно застудилася. У неї була температура, боліло горло, і вона постійно кашляла. Перші два дні вона пила чай із медом і лежала в ліжку, але їй не ставало краще. У середу вона зателефонувала своїй лікарці й записалася на огляд. Лікарка оглянула її й сказала, що в неї запалення горла. Вона дала їй рецепт на антибіотик і лікарняний до п’ятниці. Олена купила ліки в аптеці й приймала їх двічі на день. У суботу вона почувалася вже набагато краще. Наступного разу вона одразу зателефонує лікарці.', 'Текст «Олена застудилася». Правильна відповідь: «У суботу».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a23a43d7-1142-5d0a-a80d-b36ba7da7d29', v_aid, 10, 'A2', 'reading', 'understand', 'multiple_choice', 'Про що ще питає Оксана?', 'Promjena rezervacije', '["Про сніданок", "Про паркування й пляж", "Про таксі"]'::jsonb, 1, null, null, 'Poštovani,
rezervirala sam kod vas apartman od 10. do 17. srpnja za dvije odrasle osobe i jedno dijete. Nažalost, moramo promijeniti datum jer moj muž ne može dobiti godišnji odmor u srpnju. Možemo li doći od 7. do 14. kolovoza? Ako taj termin nije slobodan, molim vas da mi javite koji je tjedan u kolovozu slobodan. Također bih htjela pitati imate li parkiralište i je li plaža blizu.
Unaprijed hvala na odgovoru.
Srdačan pozdrav,
Oksana Melnyk', 'Шановні!
Я забронювала у вас апартаменти з 10 по 17 липня для двох дорослих і однієї дитини. На жаль, ми мусимо змінити дату, бо мій чоловік не може отримати відпустку в липні. Чи можемо ми приїхати з 7 по 14 серпня? Якщо ці дати не вільні, прошу, повідомте мені, який тиждень у серпні вільний. Також я хотіла б запитати, чи є у вас паркування і чи близько пляж.
Заздалегідь дякую за відповідь.
З повагою,
Оксана Мельник', 'Текст «Зміна бронювання». Правильна відповідь: «Про паркування й пляж».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('59e816f8-4cd8-5e5f-9ab0-bca6a7219cb9', v_aid, 11, 'A2', 'reading', 'understand', 'multiple_choice', 'Що нового в роботі Олени?', 'Pismo prijateljici u Ukrajini', '["Вона працює в готелі", "Вона працює в дитсадку", "Вона не працює"]'::jsonb, 1, null, null, 'Draga Ira,
dugo ti se nisam javila, oprosti! Ovdje je sve dobro. Djeca su se navikla na školu i već imaju prijatelje. Sofija je u razredu najbolja iz matematike, a Danilo igra nogomet. Ja sam promijenila posao: sada radim u vrtiću kao pomoćnica odgojiteljice. Posao mi se jako sviđa, iako je plaća mala. Hrvatski mi ide sve bolje, ali još uvijek griješim. Puno mislim na tebe i na naš grad. Kad ćeš doći u posjet? Imamo mali stan, ali za tebe ćemo naći mjesto.
Grlim te,
Olena', 'Люба Іро!
Я давно тобі не писала, вибач! Тут усе добре. Діти звикли до школи й уже мають друзів. Софія найкраща в класі з математики, а Данило грає у футбол. Я змінила роботу: тепер працюю в дитячому садку помічницею вихователя. Робота мені дуже подобається, хоча зарплата маленька. Хорватська дається мені дедалі краще, але я досі помиляюся. Я багато думаю про тебе і про наше місто. Коли ти приїдеш у гості? У нас маленька квартира, але для тебе ми знайдемо місце.
Обіймаю тебе,
Олена', 'Текст «Лист подрузі в Україну». Правильна відповідь: «Вона працює в дитсадку».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5e0ec502-740e-518c-9eae-8a73d25b5a43', v_aid, 12, 'A2', 'reading', 'understand', 'multiple_choice', 'Як жінка знайшла його номер?', 'Izgubljeni novčanik', '["У поліції", "В інтернеті", "На візитівці в гаманці"]'::jsonb, 2, null, null, 'U utorak je Taras putovao tramvajem na posao. Kad je izašao na svojoj stanici, shvatio je da nema novčanika. U novčaniku su bili osobna iskaznica, bankovna kartica i dvadeset eura. Odmah je nazvao banku i blokirao karticu. Zatim je otišao u ured za izgubljene stvari, ali novčanika tamo nije bilo. Navečer ga je nazvala nepoznata žena. Rekla je da je našla novčanik u tramvaju, a broj telefona pronašla je na posjetnici. Sljedeći dan Taras joj je donio kutiju čokolade i lijepo joj se zahvalio. Novac je bio unutra!', 'У вівторок Тарас їхав трамваєм на роботу. Коли він вийшов на своїй зупинці, то зрозумів, що в нього немає гаманця. У гаманці були посвідчення особи, банківська картка і двадцять євро. Він одразу зателефонував у банк і заблокував картку. Потім пішов у бюро знахідок, але гаманця там не було. Увечері йому зателефонувала незнайома жінка. Вона сказала, що знайшла гаманець у трамваї, а номер телефону знайшла на візитівці. Наступного дня Тарас приніс їй коробку цукерок і щиро подякував. Гроші були всередині!', 'Текст «Загублений гаманець». Правильна відповідь: «На візитівці в гаманці».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d118b176-66b8-50bb-bd1c-a27763ce280f', v_aid, 13, 'A2', 'reading', 'understand', 'multiple_choice', 'Чому Івана була вдома?', 'Kako je bilo za vikend?', '["Вона хворіла", "Ішов дощ", "Вона працювала"]'::jsonb, 0, null, null, 'Ivana: Bok, Taras! Kako je bilo za vikend?
Taras: Super! U subotu smo bili na Plitvicama. Hodali smo pet sati.
Ivana: Prekrasno! Jeste li vidjeli velike slapove?
Taras: Jesmo. Bilo je puno ljudi, ali vrijedilo je. A ti?
Ivana: Ja sam bila kod kuće. Bila sam bolesna, pa sam samo spavala i gledala filmove.
Taras: Joj, žao mi je! Je li ti sada bolje?
Ivana: Bolje mi je, hvala. Sljedeći put idem s vama!
Taras: Dogovoreno!', 'Івана: Привіт, Тарасе! Як минули вихідні?
Тарас: Чудово! У суботу ми були на Плітвицьких озерах. Ходили п’ять годин.
Івана: Чудово! Ви бачили великі водоспади?
Тарас: Бачили. Було багато людей, але воно того було варте. А ти?
Івана: Я була вдома. Я хворіла, тож тільки спала й дивилася фільми.
Тарас: Ой, шкода! Тобі вже краще?
Івана: Краще, дякую. Наступного разу піду з вами!
Тарас: Домовилися!', 'Текст «Як минули вихідні?». Правильна відповідь: «Вона хворіла».', null, 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5b3a0a4b-2e61-58dc-85a8-b489e03c5799', v_aid, 14, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?', '["„Draga Olena“. Onda napiši novosti, ukratko.", "Trebate liječničko uvjerenje iz medicine rada, putovnicu i staru dozvolu.", "Do isteka zaliha. I dostava je besplatna."]'::jsonb, 0, null, 'Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?', null, null, 'Діалог «Лист подрузі»: «Daša, pišem pismo prijateljici u Kijev. Kako da počnem na hrvatskom?» (Дашо, я пишу лист подрузі до Києва. Як почати хорватською?) — «„Draga Olena“. Onda napiši novosti, ukratko.» («Дорога Олено». Потім напиши новини, коротко.).', (select id from public.lessons where id = 'f4f20a90-406f-58fa-9369-2df5aceb93a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('021fc5f0-b86c-5ded-8e3c-8821ddb7e193', v_aid, 15, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Je li odvoz besplatan?', '["Neke lijekove ne smijete, to su zabranjeni predmeti.", "Jest, jednom godišnje.", "Kad se sve zbroji, jest."]'::jsonb, 1, null, 'Je li odvoz besplatan?', null, null, 'Діалог «Старий диван»: «Je li odvoz besplatan?» (Вивезення безкоштовне?) — «Jest, jednom godišnje.» (Так, раз на рік.).', (select id from public.lessons where id = '5ef67da9-21aa-58fa-91c2-d8144333a756'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5c052291-3418-5cfe-bafa-46427c5d0e92', v_aid, 16, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Darja, zašto si tužna?', '["Posvađala sam se sa sestrom. Rekla sam joj nešto ružno.", "Nažalost, auto nije prošao. Kočnice su istrošene.", "Starijima i nepoznatima se persira. Kolege se uglavnom tikaju."]'::jsonb, 0, null, 'Darja, zašto si tužna?', null, null, 'Діалог «Сварка з сестрою»: «Darja, zašto si tužna?» (Дар’є, чому ти сумна?) — «Posvađala sam se sa sestrom. Rekla sam joj nešto ružno.» (Я посварилася з сестрою. Я сказала їй щось негарне.).', (select id from public.lessons where id = '6fbe028c-f4c3-50b2-b282-84f62f5d4c78'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('50dca601-5a97-58fa-9c3c-fe1fc885c46f', v_aid, 17, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kako šalješ novac roditeljima?', '["Stari kauč, dva ormara i staru perilicu.", "Za masline. Želim ih posaditi na terasi.", "Preko aplikacije za plaćanje. Novac stiže za nekoliko minuta."]'::jsonb, 2, null, 'Kako šalješ novac roditeljima?', null, null, 'Діалог «Переказ»: «Kako šalješ novac roditeljima?» (Як ти надсилаєш гроші батькам?) — «Preko aplikacije za plaćanje. Novac stiže za nekoliko minuta.» (Через платіжний застосунок. Гроші надходять за кілька хвилин.).', (select id from public.lessons where id = 'bc5bde26-5065-560b-8877-1302e7048471'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('6891ed95-2682-50a7-a3d2-f8578eec33d2', v_aid, 18, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Mogu li pročitati uvjete osiguranja?', '["Kava nije piće, nego druženje. Pomalo!", "Naravno, izvolite. Policu ćete dobiti e-mailom.", "Ponekad. Ali purica s mlincima je svima razumljiva!"]'::jsonb, 1, null, 'Mogu li pročitati uvjete osiguranja?', null, null, 'Діалог «Страхування квартири»: «Mogu li pročitati uvjete osiguranja?» (Можу прочитати умови страхування?) — «Naravno, izvolite. Policu ćete dobiti e-mailom.» (Звісно, прошу. Поліс ви отримаєте e-mailом.).', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('82150ed4-d107-558f-b742-b7a255a328f1', v_aid, 19, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kao naš zbor?', '["Slično, ali manje. Klapsko pjevanje je na popisu UNESCO-a.", "Odgovara. Šteta za danas, ali nadoknadit ćemo.", "Kupila bih vikendicu na otoku i putovala bih oko svijeta."]'::jsonb, 0, null, 'Kao naš zbor?', null, null, 'Діалог «Клапа на набережній»: «Kao naš zbor?» (Як наш хор?) — «Slično, ali manje. Klapsko pjevanje je na popisu UNESCO-a.» (Схоже, але менший. Спів клапи — у списку ЮНЕСКО.).', (select id from public.lessons where id = 'c71597ab-1dac-5b9d-a304-b389f93a420a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('3cd63981-fa9c-5329-975f-d31c552c95b7', v_aid, 20, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Kad si rođena, Darja?', '["Obraćanje: „Poštovana gospođo“. Ton pisma mora biti ljubazan.", "Učim ih cijeli tjedan, ali još nisam naučila sve.", "Dvadeset prvog travnja tisuću devetsto devedesete."]'::jsonb, 2, null, 'Kad si rođena, Darja?', null, null, 'Діалог «Дати мого життя»: «Kad si rođena, Darja?» (Коли ти народилася, Дар’є?) — «Dvadeset prvog travnja tisuću devetsto devedesete.» (Двадцять першого квітня тисяча дев’ятсот дев’яностого.).', (select id from public.lessons where id = 'c8c098bc-973f-5a79-b42a-5ec5c7152d09'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('d78f2696-399a-5ce5-af03-da25f8dc42d5', v_aid, 21, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Imam dobre bilješke s vježbi. Hoćeš li ih?', '["Hoću, hvala! Bez njih ne bih znala ponoviti gradivo.", "Solidarnost. Susjedi su donirali djeci odjeću i igračke.", "Nadam se miru. Svaki dan je mali korak naprijed."]'::jsonb, 0, null, 'Imam dobre bilješke s vježbi. Hoćeš li ih?', null, null, 'Діалог «Перед іспитом»: «Imam dobre bilješke s vježbi. Hoćeš li ih?» (У мене гарний конспект із практичних. Хочеш?) — «Hoću, hvala! Bez njih ne bih znala ponoviti gradivo.» (Хочу, дякую! Без нього я б не знала, як повторити матеріал.).', (select id from public.lessons where id = '4be96321-cd99-57ff-a9bc-17cfaf4f4c29'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('9d09aa2d-4475-5ee8-98de-0543bd01937a', v_aid, 22, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Ima li skijališta?', '["Ima, malo skijalište u Platku. A djeca se mogu sanjkati.", "Moram, kad dobijem novu putovnicu. I službeniku donijeti presliku.", "Svaki dan po pola sata. Napredak pratim u bilježnici."]'::jsonb, 0, null, 'Ima li skijališta?', null, null, 'Діалог «Зима в Горському Котарі»: «Ima li skijališta?» (Є лижні схили?) — «Ima, malo skijalište u Platku. A djeca se mogu sanjkati.» (Є, невеликий схил у Платаку. А діти можуть кататися на санчатах.).', (select id from public.lessons where id = 'ab060253-8099-5e7d-bfaa-1b1a7655c229'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('7cc7fe39-5470-5cf4-9c88-4e988a11eb12', v_aid, 23, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Trebam li napisati „samo ozbiljni kupci“?', '["Počnite na tržnici Dolac, pa uspinjačom na Gornji grad.", "Može. I stavi kontakt na dno oglasa.", "U zakonskom roku, do trideset dana. Rješenje se šalje poštom."]'::jsonb, 1, null, 'Trebam li napisati „samo ozbiljni kupci“?', null, null, 'Діалог «Продаю візок»: «Trebam li napisati „samo ozbiljni kupci“?» (Треба написати «лише серйозні покупці»?) — «Može. I stavi kontakt na dno oglasa.» (Можна. І постав контакт унизу оголошення.).', (select id from public.lessons where id = '3fc81316-dca8-5661-88c1-eaf2b61aec07'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('47b71a8a-423c-5f4f-9be6-5228ba4c355b', v_aid, 24, 'A2', 'interaction', 'interact', 'multiple_choice', 'Вам кажуть. Що доречно відповісти?', 'Jeste li naručili termin online?', '["Volio bih naučiti svirati gitaru.", "Fiš paprikaš je kao naša juha, samo ljući!", "Jesam, za deset sati. Ovo su putovnice i iskaznice stranca."]'::jsonb, 2, null, 'Jeste li naručili termin online?', null, null, 'Діалог «Продовження статусу»: «Jeste li naručili termin online?» (Ви записувалися онлайн?) — «Jesam, za deset sati. Ovo su putovnice i iskaznice stranca.» (Так, на десяту. Ось паспорти й посвідки іноземця.).', (select id from public.lessons where id = '5e298915-e179-5d58-bca0-6531c7b43a46'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('ccfd8fd0-19a5-5474-a31a-0802bf4bcdea', v_aid, 25, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Dobit ću i novu naljepnicu?', '["Відремонтуйте гальма. Повторний огляд безкоштовний протягом п’ятнадцяти днів.", "Так, коли авто пройде огляд.", "Перейдіть до каси. Там ви сплачуєте й обов’язкову страховку."]'::jsonb, 1, null, null, 'Kontrolor: Popravite kočnice. Ponovni pregled je besplatan u roku od petnaest dana.
Ivan: Dobro. A gdje plaćam registraciju?
Kontrolor: Prijeđite na blagajnu. Tamo plaćate i obvezno osiguranje.
Ivan: Dobit ću i novu naljepnicu?
Kontrolor: Da, kad auto prođe pregled.', 'Kontrolor: Відремонтуйте гальма. Повторний огляд безкоштовний протягом п’ятнадцяти днів.
Ivan: Добре. А де я плачу за реєстрацію?
Kontrolor: Перейдіть до каси. Там ви сплачуєте й обов’язкову страховку.
Ivan: Я отримаю й нову наліпку?
Kontrolor: Так, коли авто пройде огляд.', 'Діалог «Повторний огляд»: «Dobit ću i novu naljepnicu?» — «Da, kad auto prođe pregled.», тобто «Так, коли авто пройде огляд.».', (select id from public.lessons where id = 'c689f4db-1707-535b-a2cd-0f244b663854'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5d165920-0320-5ff5-ad3d-c4b7b580ddbc', v_aid, 26, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Ambiciozno! Kako ćeš ostvariti cilj s ispitom?', '["Побачимо. Потрібна наполегливість.", "Тільки не здайся в лютому!", "Щодня по пів години. За прогресом стежу в зошиті."]'::jsonb, 2, null, null, 'Daša: Darja, imaš li novogodišnju odluku?
Darja: Imam tri cilja. Položit ću ispit B1, uštedjet ću za more i promijenit ću posao.
Daša: Ambiciozno! Kako ćeš ostvariti cilj s ispitom?
Darja: Svaki dan po pola sata. Napredak pratim u bilježnici.
Daša: Samo nemoj odustati u veljači!
Darja: Vidjet ćemo. Treba ustrajnosti.', 'Daša: Дар’є, у тебе є новорічна обіцянка?
Darja: У мене три цілі. Складу іспит B1, заощаджу на море й поміняю роботу.
Daša: Амбітно! Як ти досягнеш мети з іспитом?
Darja: Щодня по пів години. За прогресом стежу в зошиті.
Daša: Тільки не здайся в лютому!
Darja: Побачимо. Потрібна наполегливість.', 'Діалог «Новорічні обіцянки»: «Ambiciozno! Kako ćeš ostvariti cilj s ispitom?» — «Svaki dan po pola sata. Napredak pratim u bilježnici.», тобто «Щодня по пів години. За прогресом стежу в зошиті.».', (select id from public.lessons where id = 'f2760130-fd69-5932-978c-cc424aaefafa'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('afbe4065-7278-5733-993e-f53c901dfd65', v_aid, 27, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jesi li bio u onom novom restoranu u centru?', '["Шкода. А якийсь кращий?", "Маленька конова за ринком. Співвідношення ціни й якості чудове.", "Так. Чесно, він переоцінений. Їжа посередня, а ціни високі."]'::jsonb, 2, null, null, 'Ivan: Jesi li bio u onom novom restoranu u centru?
Marko: Jesam. Iskreno, precijenjen je. Hrana je prosječna, a cijene visoke.
Ivan: Šteta. A neki bolji?
Marko: Mala konoba iza tržnice. Omjer cijene i kvalitete je odličan.', 'Ivan: Ти був у тому новому ресторані в центрі?
Marko: Так. Чесно, він переоцінений. Їжа посередня, а ціни високі.
Ivan: Шкода. А якийсь кращий?
Marko: Маленька конова за ринком. Співвідношення ціни й якості чудове.', 'Діалог «Ресторан»: «Jesi li bio u onom novom restoranu u centru?» — «Jesam. Iskreno, precijenjen je. Hrana je prosječna, a cijene visoke.», тобто «Так. Чесно, він переоцінений. Їжа посередня, а ціни високі.».', (select id from public.lessons where id = '57ba42b9-17e0-5dda-9de1-f0354b45f845'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('315fb71f-5a28-565b-8fce-5190b59f3863', v_aid, 28, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Na stražnjim vratima je ogrebotina. Možete li to zapisati?', '["Звісно. Якщо повернете авто з повним баком, нічого не платите.", "Добрий день, у мене бронь на маленьке авто з автоматичною коробкою.", "Триста євро, ми заблокуємо їх на картці. Авто з повним баком."]'::jsonb, 0, null, null, 'Daša: Dobar dan, imam rezervaciju za mali auto s automatskim mjenjačem.
Službenik: Izvolite. Hoćete li kasko osiguranje? Bez njega je franšiza tisuću eura.
Daša: Hoću. A kolika je kaucija?
Službenik: Tristo eura, blokirat ćemo ih na kartici. Auto je s punim spremnikom.
Daša: Na stražnjim vratima je ogrebotina. Možete li to zapisati?
Službenik: Naravno. Ako vratite auto s punim spremnikom, ništa ne plaćate.', 'Daša: Добрий день, у мене бронь на маленьке авто з автоматичною коробкою.
Službenik: Прошу. Бажаєте страхування каско? Без нього франшиза тисяча євро.
Daša: Так. А яка застава?
Službenik: Триста євро, ми заблокуємо їх на картці. Авто з повним баком.
Daša: На задніх дверях подряпина. Можете це записати?
Službenik: Звісно. Якщо повернете авто з повним баком, нічого не платите.', 'Діалог «У прокаті»: «Na stražnjim vratima je ogrebotina. Možete li to zapisati?» — «Naravno. Ako vratite auto s punim spremnikom, ništa ne plaćate.», тобто «Звісно. Якщо повернете авто з повним баком, нічого не платите.».', (select id from public.lessons where id = '35e0e7d1-e7a5-5633-8656-21231dc30640'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('0b68e9d7-d2a3-5bc0-bad7-26bc96fced77', v_aid, 29, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Jesu li stigli moji nalazi?', '["Так, лікарі вам їх пояснять.", "Ваше ім’я? Так, ось ви в картці. Сідайте, я виміряю вам тиск.", "Дякую. І ще в мене синець на нозі."]'::jsonb, 0, null, null, 'Ivan: Dobar dan, imam termin za pregled u devet.
Sestra: Vaše ime? Da, tu ste u kartonu. Sjednite, izmjerit ću Vam tlak.
Ivan: Jesu li stigli moji nalazi?
Sestra: Jesu, liječnici će Vam ih objasniti.
Ivan: Hvala. I još imam modricu na nozi.', 'Ivan: Добрий день, у мене огляд о дев’ятій.
Sestra: Ваше ім’я? Так, ось ви в картці. Сідайте, я виміряю вам тиск.
Ivan: Мої результати вже прийшли?
Sestra: Так, лікарі вам їх пояснять.
Ivan: Дякую. І ще в мене синець на нозі.', 'Діалог «У медсестри»: «Jesu li stigli moji nalazi?» — «Jesu, liječnici će Vam ih objasniti.», тобто «Так, лікарі вам їх пояснять.».', (select id from public.lessons where id = '468ce636-fdba-5b52-9695-dc9daa6a032b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('240b03a3-5213-5daf-af71-39ed3e8352e7', v_aid, 30, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг поруч не знає хорватської. Перекажіть йому українською, що відповіли на питання:', 'Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?', '["Це пенсійний внесок. Його віднімають від брутто-зарплати.", "Можете. Принесіть нам їхні дані, і ми змінимо податкову картку.", "Минулого місяця у вас була доплата за нічну роботу."]'::jsonb, 1, null, null, 'Darja: Dobar dan, imam pitanje o platnoj listi. Biste li mi objasnili ovu stavku?
Računovotkinja: To je mirovinski doprinos. On se odbija od bruto plaće.
Darja: A zašto mi je neto plaća manja nego prošli mjesec?
Računovotkinja: Prošli mjesec ste imali dodatak za noćni rad.
Darja: Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?
Računovotkinja: Možete. Donesite nam njihove podatke i promijenit ćemo poreznu karticu.', 'Darja: Добрий день, у мене питання щодо розрахункового листа. Чи не пояснили б ви цей пункт?
Računovotkinja: Це пенсійний внесок. Його віднімають від брутто-зарплати.
Darja: А чому моя нетто-зарплата менша, ніж минулого місяця?
Računovotkinja: Минулого місяця у вас була доплата за нічну роботу.
Darja: Зрозуміло. У мене двоє дітей. Чи можу я мати більшу неоподатковувану суму?
Računovotkinja: Можете. Принесіть нам їхні дані, і ми змінимо податкову картку.', 'Діалог «Розрахунковий лист»: «Razumijem. Imam dvoje djece. Mogu li imati veći osobni odbitak?» — «Možete. Donesite nam njihove podatke i promijenit ćemo poreznu karticu.», тобто «Можете. Принесіть нам їхні дані, і ми змінимо податкову картку.».', (select id from public.lessons where id = 'b9bcea21-08a3-56cf-be72-edf6b6c7b03f'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('16602d0d-745e-5958-9f52-fb7482bec500', v_aid, 31, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Де я плачу за реєстрацію?». Що ви скажете?', null, '["Gdje plaćam registraciju?", "Moj auto nije prošao tehnički pregled.", "Možemo li zaobići zastoj?"]'::jsonb, 0, null, null, null, null, '«Де я плачу за реєстрацію?» — «Gdje plaćam registraciju?».', (select id from public.lessons where id = 'c689f4db-1707-535b-a2cd-0f244b663854'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('bdf68bbf-f40e-552f-8fd9-c100152e54ff', v_aid, 32, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Що покриває поліс?». Що ви скажете?', null, '["Gdje se predaje zahtjev?", "Može li se potvrda dobiti elektronički?", "Što pokriva polica?"]'::jsonb, 2, null, null, null, null, '«Що покриває поліс?» — «Što pokriva polica?».', (select id from public.lessons where id = 'f3cfca9e-efc9-5b58-8fe9-772fa631e0c2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f4c3ddd0-b01d-5ca8-9592-d48d26008141', v_aid, 33, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Це не обов’язково, але рекомендовано». Що ви скажете?', null, '["Dogovoreno, vidimo se u osam!", "Nije obvezno, ali je preporučeno.", "Štedimo za novi auto."]'::jsonb, 1, null, null, null, null, '«Це не обов’язково, але рекомендовано.» — «Nije obvezno, ali je preporučeno.».', (select id from public.lessons where id = 'b8615bf1-2cc2-5cc1-b89a-ed065a4b9c28'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e1199ea9-73a4-5857-97a8-65c6a732e262', v_aid, 34, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Який наступний крок?». Що ви скажете?', null, '["Koji je sljedeći korak?", "Je li staza dobro označena?", "Moj cilj je promijeniti posao."]'::jsonb, 0, null, null, null, null, '«Який наступний крок?» — «Koji je sljedeći korak?».', (select id from public.lessons where id = 'e7b7f159-25f2-53dc-b20e-df56f5dae94b'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5eb210a9-1d07-5e94-b906-a24acb4afc53', v_aid, 35, 'A2', 'mediation', 'mediate', 'multiple_choice', 'Друг-українець просить вас сказати хорватською: «Мені не продовжили договір». Що ви скажете?', null, '["Htjela bih otvoriti obrt.", "Nisu mi produžili ugovor.", "Možete li joj prenijeti poruku?"]'::jsonb, 1, null, null, null, null, '«Мені не продовжили договір.» — «Nisu mi produžili ugovor.».', (select id from public.lessons where id = '3ceb812b-6a68-5204-beba-52e0cb3031ad'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('526d06cc-f689-5839-b65a-6a0f09469aef', v_aid, 36, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «з’єднати»', null, '[]'::jsonb, null, 'spojiti', null, null, null, '«з’єднати» — spojiti.', (select id from public.lessons where id = 'd7b6bad3-d46a-5f73-b796-dca7b1538853'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('24b83d9b-4494-5601-9b18-23a98e49eac2', v_aid, 37, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «наприклад»', null, '[]'::jsonb, null, 'primjerice', null, null, null, '«наприклад» — primjerice.', (select id from public.lessons where id = 'd6b9db92-a933-5d45-8f17-f6e911a97ab1'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('69399697-0ab5-5cf3-b17b-d7cb66aeface', v_aid, 38, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «електронно»', null, '[]'::jsonb, null, 'elektronički', null, null, null, '«електронно» — elektronički.', (select id from public.lessons where id = '5f9af92b-06e1-5179-81a3-19625a5b8273'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('c5362380-c0fe-5ce4-88b1-1431cdffb44c', v_aid, 39, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «відбиток пальця»', null, '[]'::jsonb, null, 'otisak prsta', null, null, null, '«відбиток пальця» — otisak prsta.', (select id from public.lessons where id = '5e298915-e179-5d58-bca0-6531c7b43a46'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('5bc244f6-4e9b-50a9-a4d1-59b2a04d3b13', v_aid, 40, 'A2', 'writing', 'produce', 'type_answer', 'Напишіть хорватською: «туга»', null, '[]'::jsonb, null, 'čežnja', null, null, null, '«туга» — čežnja.', (select id from public.lessons where id = '3dfc3a66-be3b-5760-8273-f00b5cb03871'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('a7cb2965-f22b-50c9-bd6e-e503d20f5e8d', v_aid, 41, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Твоє повідомлення мене дуже потішило.»', null, '["me", "jako", "poruka", "Tvoja", "obradovala."]'::jsonb, null, 'Tvoja poruka me jako obradovala.', null, null, null, '«Твоє повідомлення мене дуже потішило.» — «Tvoja poruka me jako obradovala.».', (select id from public.lessons where id = '75a84442-280d-56be-b746-81ca57caa0b5'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('b56d7940-25be-568b-8ae7-b8ffa52af64b', v_aid, 42, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Годувати тварин заборонено.»', null, '["životinje.", "hraniti", "je", "Zabranjeno"]'::jsonb, null, 'Zabranjeno je hraniti životinje.', null, null, null, '«Годувати тварин заборонено.» — «Zabranjeno je hraniti životinje.».', (select id from public.lessons where id = 'b9b0bb4b-ffcb-56e0-bbb0-a927fffa9f39'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('cf3d9e63-ec26-5d1c-9e16-3b41420fb5ce', v_aid, 43, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «На наступному з’їзді поверніть праворуч.»', null, '["desno.", "skrenite", "Na", "sljedećem", "izlazu"]'::jsonb, null, 'Na sljedećem izlazu skrenite desno.', null, null, null, '«На наступному з’їзді поверніть праворуч.» — «Na sljedećem izlazu skrenite desno.».', (select id from public.lessons where id = '161ebc1e-5359-551e-82a5-ddd878ceb97a'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('f6ca7922-cbbd-5578-b5f8-5e93a474ca96', v_aid, 44, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Сьогодні йому вже краще.»', null, '["mu", "Danas", "bolje.", "već", "je"]'::jsonb, null, 'Danas mu je već bolje.', null, null, null, '«Сьогодні йому вже краще.» — «Danas mu je već bolje.».', (select id from public.lessons where id = '8f08356b-8efa-5ebc-906e-f409fbaadaf3'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('718532b2-80c4-5dc2-9446-946d87b3781a', v_aid, 45, 'A2', 'writing', 'produce', 'sentence_builder', 'Складіть: «Підпишіть згоду на екскурсію.»', null, '["Potpišite", "izlet.", "suglasnost", "za"]'::jsonb, null, 'Potpišite suglasnost za izlet.', null, null, null, '«Підпишіть згоду на екскурсію.» — «Potpišite suglasnost za izlet.».', (select id from public.lessons where id = 'e32cdbd5-0e59-53c7-8773-bf31e69068a2'), 'PUBLISHED', 'claude_assessment_a2_v2'),
  ('e3cb0ac2-3302-556a-8d6d-a48b2b530fbc', v_aid, 46, 'A2', 'speaking', 'produce', 'speaking', 'Скажіть хорватською: «Коли в професорки консультації?»', null, '[]'::jsonb, null, 'Kada profesorica ima konzultacije?', null, null, null, '«Коли в професорки консультації?» — «Kada profesorica ima konzultacije?».', (select id from public.lessons where id = '4be96321-cd99-57ff-a9bc-17cfaf4f4c29'), 'PUBLISHED', 'claude_assessment_a2_v2'),
