-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_bad int; v_total int;
begin
  select count(*) into v_bad from (values ('a2-m01', 16), ('a2-m02', 16), ('a2-m03', 12), ('a2-m04', 14), ('a2-m05', 14), ('a2-m06', 12), ('a2-m07', 12), ('a2-m08', 12), ('a2-m09', 12), ('a2-m10', 12), ('a2-m11', 12), ('a2-m12', 12), ('a2-m13', 12), ('a2-m14', 12), ('a2-mid', 30), ('a2-final', 48)) e(slug, n) left join public.assessments a on a.slug = e.slug and a.cefr = 'A2' and a.status = 'PUBLISHED'
   where a.id is null or (select count(*) from public.assessment_items i where i.assessment_id = a.id and i.status = 'PUBLISHED') <> e.n;
  select count(*) into v_total from public.assessment_items i join public.assessments a on a.id = i.assessment_id
   where a.cefr = 'A2' and a.source = 'claude_assessment_a2_v2' and i.status = 'PUBLISHED';
  if v_bad > 0 or v_total <> 258 then raise exception 'Перевірки A2: тестів з помилкою %, завдань % (очікувалось 258)', v_bad, v_total; end if;
  raise notice 'Готово: перевірки рівня A2 — 16 тестів, % завдань', v_total;
end $$;

commit;
